import { GoogleGenAI, Content, Part } from "@google/genai";
import { Message, Sender } from "../types";
import { MODEL_NAME, BASE_SYSTEM_INSTRUCTION, FLIRT_LEVEL_INSTRUCTIONS, ROLEPLAY_EXAMPLES } from "../constants";

let client: GoogleGenAI | null = null;

const getClient = (): GoogleGenAI => {
  if (!client) {
    const apiKey = process.env.API_KEY || ''; 
    client = new GoogleGenAI({ apiKey });
  }
  return client;
};

export const sendMessageToGemini = async (
  currentMessage: string,
  history: Message[],
  memoryEnabled: boolean,
  flirtLevel: number,
  customMemory: string
): Promise<string> => {
  try {
    const ai = getClient();

    // Construct Dynamic System Instruction
    const flirtInstruction = FLIRT_LEVEL_INSTRUCTIONS[flirtLevel as keyof typeof FLIRT_LEVEL_INSTRUCTIONS] || FLIRT_LEVEL_INSTRUCTIONS[3];

    const finalSystemInstruction = `
      ${BASE_SYSTEM_INSTRUCTION}

      CURRENT SETTINGS:
      ${flirtInstruction}

      USER'S CUSTOM MEMORY/INSTRUCTIONS:
      ${customMemory ? `"${customMemory}" - (You MUST strictly follow this memory/instruction)` : "No specific custom memory set."}

      ${ROLEPLAY_EXAMPLES}
    `;

    // Transform internal history to Gemini Content format
    let geminiHistory: Content[] = [];

    if (memoryEnabled) {
      geminiHistory = history.map((msg) => ({
        role: msg.sender,
        parts: [{ text: msg.text } as Part],
      }));
    }

    const chat = ai.chats.create({
      model: MODEL_NAME,
      config: {
        systemInstruction: finalSystemInstruction,
      },
      history: geminiHistory,
    });

    const result = await chat.sendMessage({
      message: currentMessage
    });

    return result.text || "";
  } catch (error) {
    console.error("Error communicating with Arohi:", error);
    return "Baby, I'm having a little trouble hearing you right now... say that again? 🥺";
  }
};

