import React, { useState, useRef, useEffect } from 'react';
import { Send, Menu, Plus, Settings, Sparkles, User, Mic, Trash2 } from 'lucide-react';
import { Message, Sender, ChatSession, AppSettings } from '../types';
import { INITIAL_GREETING } from '../constants';

interface ChatInterfaceProps {
  currentChatId: string | null;
  chats: ChatSession[];
  settings: AppSettings;
  onSendMessage: (text: string) => Promise<void>;
  onNewChat: () => void;
  onSelectChat: (id: string) => void;
  onDeleteChat: (id: string) => void;
  onOpenSettings: () => void;
  isLoading: boolean;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  currentChatId,
  chats,
  onSendMessage,
  onNewChat,
  onSelectChat,
  onDeleteChat,
  onOpenSettings,
  isLoading
}) => {
  const [inputText, setInputText] = useState('');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  // Ref to prevent double submission
  const isSendingRef = useRef(false);

  const activeChat = chats.find(c => c.id === currentChatId);
  const messages = activeChat ? activeChat.messages : [];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = textareaRef.current.scrollHeight + 'px';
    }
  }, [inputText]);

  const handleSend = async () => {
    const text = inputText.trim();
    if (!text || isLoading || isSendingRef.current) return;

    // Set guard
    isSendingRef.current = true;

    setInputText('');
    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      await onSendMessage(text);
    } finally {
      // Release guard
      isSendingRef.current = false;
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex h-screen bg-slate-900 overflow-hidden">

      {/* Sidebar Overlay for Mobile */}
      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-20 lg:hidden backdrop-blur-sm"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <div className={`fixed lg:static inset-y-0 left-0 z-30 w-72 bg-slate-900 border-r border-slate-800 transform transition-transform duration-300 ease-in-out ${sidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'} flex flex-col`}>
        <div className="p-5 flex items-center justify-between border-b border-slate-800/50">
          <div className="flex items-center space-x-2 text-pink-400">
            <Sparkles className="w-6 h-6" />
            <span className="font-bold text-xl tracking-wide text-white">Arohi</span>
          </div>
          <button onClick={onNewChat} className="p-2 hover:bg-slate-800 rounded-full transition-colors text-slate-400 hover:text-white">
            <Plus className="w-5 h-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
           <div className="text-xs font-semibold text-slate-500 uppercase tracking-wider px-3 mb-2 mt-2">Memory</div>
           {chats.map(chat => (
             <div key={chat.id} className="group flex items-center space-x-1">
               <button
                 onClick={() => {
                   onSelectChat(chat.id);
                   setSidebarOpen(false);
                 }}
                 className={`flex-1 text-left p-3 rounded-xl transition-all duration-200 text-sm truncate flex items-center space-x-3 ${chat.id === currentChatId ? 'bg-pink-900/20 text-pink-300 border border-pink-500/20' : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'}`}
               >
                 <span className="truncate">{chat.title}</span>
               </button>
               <button 
                 onClick={(e) => {
                   e.stopPropagation();
                   if(window.confirm('Delete this memory?')) onDeleteChat(chat.id);
                 }}
                 className="p-2 text-slate-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"
               >
                 <Trash2 className="w-4 h-4" />
               </button>
             </div>
           ))}
           {chats.length === 0 && (
             <div className="px-3 text-sm text-slate-600 italic">No history yet.</div>
           )}
        </div>

        <div className="p-4 border-t border-slate-800/50">
          <button 
            onClick={onOpenSettings}
            className="flex items-center space-x-3 text-slate-400 hover:text-white transition-colors w-full p-2 hover:bg-slate-800 rounded-xl"
          >
            <Settings className="w-5 h-5" />
            <span className="font-medium">Settings</span>
          </button>
        </div>
      </div>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col h-full relative">
        {/* Header (Mobile Only mostly) */}
        <div className="lg:hidden h-16 border-b border-slate-800 flex items-center px-4 justify-between bg-slate-900/95 backdrop-blur z-10">
          <button onClick={() => setSidebarOpen(true)} className="text-slate-300">
            <Menu className="w-6 h-6" />
          </button>
          <span className="font-medium text-white">Arohi AI</span>
          <div className="w-6"></div> 
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6">
          {messages.length === 0 ? (
             <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-4 opacity-50">
                <Sparkles className="w-12 h-12 text-pink-500/50" />
                <p>{INITIAL_GREETING}</p>
             </div>
          ) : (
            messages.map((msg) => (
              <div 
                key={msg.id} 
                className={`flex w-full ${msg.sender === Sender.User ? 'justify-end' : 'justify-start'}`}
              >
                <div className={`flex max-w-[85%] md:max-w-[70%] ${msg.sender === Sender.User ? 'flex-row-reverse' : 'flex-row'} items-end space-x-2 space-x-reverse`}>

                  {/* Avatar */}
                  <div className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center ${msg.sender === Sender.User ? 'bg-cyan-600 ml-2' : 'bg-pink-600 mr-2'}`}>
                    {msg.sender === Sender.User ? <User className="w-5 h-5 text-white" /> : <Sparkles className="w-4 h-4 text-white" />}
                  </div>

                  {/* Bubble */}
                  <div className={`p-4 rounded-2xl text-sm md:text-base leading-relaxed whitespace-pre-wrap ${
                    msg.sender === Sender.User 
                      ? 'bg-cyan-600 text-white rounded-br-none shadow-lg shadow-cyan-900/20' 
                      : 'bg-slate-800 text-slate-200 rounded-bl-none border border-slate-700/50 shadow-lg'
                  }`}>
                    {msg.text}
                  </div>
                </div>
              </div>
            ))
          )}
          {isLoading && (
            <div className="flex justify-start w-full">
               <div className="flex items-end space-x-2">
                  <div className="w-8 h-8 rounded-full bg-pink-600 flex items-center justify-center animate-pulse">
                    <Sparkles className="w-4 h-4 text-white" />
                  </div>
                  <div className="bg-slate-800 p-4 rounded-2xl rounded-bl-none border border-slate-700/50">
                    <div className="flex space-x-1">
                      <div className="w-2 h-2 bg-pink-400 rounded-full animate-bounce"></div>
                      <div className="w-2 h-2 bg-pink-400 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></div>
                      <div className="w-2 h-2 bg-pink-400 rounded-full animate-bounce" style={{animationDelay: '0.4s'}}></div>
                    </div>
                  </div>
               </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-4 md:p-6 bg-gradient-to-t from-slate-900 to-slate-900/0">
          <div className="max-w-3xl mx-auto relative flex items-end space-x-2 bg-slate-800/80 backdrop-blur-md border border-slate-700 rounded-3xl p-2 shadow-2xl">
            <button className="p-3 text-slate-400 hover:text-pink-400 transition-colors">
               <Mic className="w-5 h-5" />
            </button>
            <textarea
              ref={textareaRef}
              rows={1}
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Talk to Arohi..."
              className="flex-1 bg-transparent border-0 focus:ring-0 text-slate-200 placeholder-slate-500 resize-none py-3 max-h-32 scrollbar-hide"
            />
            <button 
              onClick={handleSend}
              disabled={isLoading || !inputText.trim()}
              className={`p-3 rounded-full transition-all duration-200 ${
                inputText.trim() && !isLoading 
                  ? 'bg-pink-600 text-white hover:bg-pink-500 shadow-lg shadow-pink-500/20' 
                  : 'bg-slate-700 text-slate-500 cursor-not-allowed'
              }`}
            >
              <Send className="w-5 h-5" />
            </button>
          </div>
        </div>

      </div>
    </div>
  );
};

export default ChatInterface;

import React, { useState, useEffect } from 'react';
import HomeHero from './components/HomeHero';
import ChatInterface from './components/ChatInterface';
import SettingsModal from './components/SettingsModal';
import { ChatSession, AppSettings, Message, Sender } from './types';
import { sendMessageToGemini } from './services/geminiService';

// Simple UUID generator polyfill
const generateId = () => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [view, setView] = useState<'home' | 'chat'>('home');
  const [chats, setChats] = useState<ChatSession[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const [settings, setSettings] = useState<AppSettings>({
    memoryEnabled: true,
    theme: 'dark',
    flirtLevel: 3, // Default level
    customMemory: ''
  });

  // Load from LocalStorage
  useEffect(() => {
    const savedChats = localStorage.getItem('arohi_chats');
    const savedSettings = localStorage.getItem('arohi_settings');

    if (savedChats) {
      try {
        setChats(JSON.parse(savedChats));
      } catch (e) { console.error('Failed to parse chats', e); }
    }

    if (savedSettings) {
      try {
        const parsed = JSON.parse(savedSettings);
        // Merge defaults to ensure new fields exist
        setSettings(prev => ({ ...prev, ...parsed }));
      } catch (e) { console.error('Failed to parse settings', e); }
    }
  }, []);

  // Save to LocalStorage
  useEffect(() => {
    localStorage.setItem('arohi_chats', JSON.stringify(chats));
  }, [chats]);

  useEffect(() => {
    localStorage.setItem('arohi_settings', JSON.stringify(settings));
  }, [settings]);

  const createNewChat = () => {
    const newChat: ChatSession = {
      id: generateId(),
      title: 'New Conversation',
      messages: [],
      createdAt: Date.now(),
      updatedAt: Date.now()
    };
    setChats(prev => [newChat, ...prev]);
    setCurrentChatId(newChat.id);
    setView('chat');
  };

  const deleteChat = (id: string) => {
    setChats(prev => prev.filter(c => c.id !== id));
    if (currentChatId === id) {
      setCurrentChatId(null);
      // If no chats left, go home, otherwise go to most recent
      const remaining = chats.filter(c => c.id !== id);
      if (remaining.length === 0) {
        setView('home');
      } else {
        setCurrentChatId(remaining[0].id);
      }
    }
  };

  const handleStartChat = () => {
    if (chats.length > 0) {
      setCurrentChatId(chats[0].id);
      setView('chat');
    } else {
      createNewChat();
    }
  };

  const handleSendMessage = async (text: string) => {
    if (!currentChatId) return;

    // 1. Add User Message
    const userMsg: Message = {
      id: generateId(),
      text,
      sender: Sender.User,
      timestamp: Date.now()
    };

    // Update state synchronously for UI
    setChats(prev => prev.map(c => {
      if (c.id === currentChatId) {
        const newTitle = c.messages.length === 0 ? (text.slice(0, 30) + (text.length > 30 ? '...' : '')) : c.title;
        return {
          ...c,
          title: newTitle,
          messages: [...c.messages, userMsg],
          updatedAt: Date.now()
        };
      }
      return c;
    }));

    setIsLoading(true);

    try {
      // 2. Get AI Response
      // Retrieve fresh session reference to get accurate history
      const currentSessions = [...chats]; // Note: This might be stale in closure, but state update above is scheduled.
      // However, we can trust the previous state update logic or just pass the history we KNOW we have plus the new message.
      const activeChat = chats.find(c => c.id === currentChatId);
      const history = activeChat ? activeChat.messages : [];
      // Note: activeChat.messages here DOES NOT contain userMsg yet because of closure scope!
      // We must append userMsg manually for the API call context
      const fullHistory = [...history, userMsg];

      const responseText = await sendMessageToGemini(
        text, 
        fullHistory, 
        settings.memoryEnabled, 
        settings.flirtLevel || 3,
        settings.customMemory || ''
      );

      // 3. Add AI Message
      const botMsg: Message = {
        id: generateId(),
        text: responseText,
        sender: Sender.Bot,
        timestamp: Date.now()
      };

      setChats(prev => prev.map(c => {
        if (c.id === currentChatId) {
          // CRITICAL FIX: Do NOT re-add userMsg. Only add botMsg to the end of whatever is there.
          return {
            ...c,
            messages: [...c.messages, botMsg], 
            updatedAt: Date.now()
          };
        }
        return c;
      }));
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const clearAllData = () => {
    setChats([]);
    setCurrentChatId(null);
    setView('home');
    setIsSettingsOpen(false);
    localStorage.removeItem('arohi_chats');
  };

  return (
    <div className="font-sans text-slate-200">
      {view === 'home' ? (
        <HomeHero onStartChat={handleStartChat} />
      ) : (
        <ChatInterface 
          currentChatId={currentChatId}
          chats={chats}
          settings={settings}
          onSendMessage={handleSendMessage}
          onNewChat={createNewChat}
          onSelectChat={setCurrentChatId}
          onDeleteChat={deleteChat}
          onOpenSettings={() => setIsSettingsOpen(true)}
          isLoading={isLoading}
        />
      )}

      <SettingsModal 
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        onUpdateSettings={setSettings}
        onClearAllData={clearAllData}
      />
    </div>
  );
};

export default App;

