import { GoogleGenAI, Content, Part, Modality } from "@google/genai";
import { Message, Sender, GeminiResponse } from "../types";
import { 
  MODEL_CHAT, 
  MODEL_VISION, 
  MODEL_IMAGE_GEN_PRO,
  MODEL_IMAGE_GEN_FAST,
  MODEL_TTS,
  BASE_SYSTEM_INSTRUCTION, 
  FLIRT_LEVEL_INSTRUCTIONS, 
  ROLEPLAY_EXAMPLES 
} from "../constants";

// Helper to clean base64 string
const cleanBase64 = (b64: string) => {
  return b64.replace(/^data:(image|audio)\/(png|jpeg|jpg|webp|mp3|wav|pcm);base64,/, "");
};

// Heuristic to detect image generation requests
const isImageGenerationRequest = (text: string): boolean => {
  const lower = text.toLowerCase();
  const triggers = [
    "generate image", "generate an image", "create image", "create an image",
    "draw", "paint", "sketch", "make a picture", "picture of", "image of",
    "illustrate", "show me a"
  ];
  return triggers.some(t => lower.includes(t));
};

export const sendMessageToGemini = async (
  currentMessage: string,
  attachment: string | undefined,
  history: Message[],
  memoryEnabled: boolean,
  flirtLevel: number,
  customMemory: string,
  imageResolution: '1K' | '2K' | '4K'
): Promise<GeminiResponse> => {
  try {
    const apiKey = process.env.API_KEY || '';
    const ai = new GoogleGenAI({ apiKey });

    // Construct Dynamic System Instruction
    const flirtInstruction = FLIRT_LEVEL_INSTRUCTIONS[flirtLevel as keyof typeof FLIRT_LEVEL_INSTRUCTIONS] || FLIRT_LEVEL_INSTRUCTIONS[3];
    const finalSystemInstruction = `
      ${BASE_SYSTEM_INSTRUCTION}
      CURRENT SETTINGS: ${flirtInstruction}
      USER'S CUSTOM MEMORY: ${customMemory ? `"${customMemory}"` : "None."}
      ${ROLEPLAY_EXAMPLES}
    `;

    // CASE 1: USER SENDS IMAGE (VISION)
    if (attachment) {
      const response = await ai.models.generateContent({
        model: MODEL_VISION,
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: cleanBase64(attachment) } },
            { text: currentMessage || "What do you see in this photo, baby?" }
          ]
        },
        config: {
          systemInstruction: finalSystemInstruction
        }
      });
      return { text: response.text || "You look amazing, love! 💖" };
    }

    // CASE 2: USER REQUESTS IMAGE GENERATION
    if (isImageGenerationRequest(currentMessage)) {
      // Use Pro model only if user specifically asks for high res settings in prompt or config implies it
      // Default to Flash Image for speed and "free" availability unless 4K is requested
      const usePro = imageResolution === '4K' || imageResolution === '2K';
      const modelToUse = usePro ? MODEL_IMAGE_GEN_PRO : MODEL_IMAGE_GEN_FAST;

      // Note: Flash Image (Nano Banana) doesn't support imageSize config, only Pro does.
      const imageConfig = usePro ? {
        aspectRatio: "1:1",
        imageSize: imageResolution
      } : {
        aspectRatio: "1:1"
      };

      const response = await ai.models.generateContent({
        model: modelToUse,
        contents: {
          parts: [{ text: currentMessage }]
        },
        config: {
          imageConfig: imageConfig as any
        }
      });

      let generatedImage = "";
      let generatedText = "";

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            generatedImage = `data:image/png;base64,${part.inlineData.data}`;
          } else if (part.text) {
            generatedText += part.text;
          }
        }
      }

      return {
        text: generatedText || "Here's the picture you wanted, sweetheart. Do you like it? 🎨",
        attachment: generatedImage
      };
    }

    // CASE 3: STANDARD CHAT
    let geminiHistory: Content[] = [];
    if (memoryEnabled) {
      geminiHistory = history
        .filter(m => !m.attachment) // Filter out heavy image messages from history context for standard chat
        .map((msg) => ({
          role: msg.sender,
          parts: [{ text: msg.text } as Part],
        }));
    }

    const chat = ai.chats.create({
      model: MODEL_CHAT,
      config: { systemInstruction: finalSystemInstruction },
      history: geminiHistory,
    });

    const result = await chat.sendMessage({ message: currentMessage });
    return { text: result.text || "" };

  } catch (error) {
    console.error("Gemini Error:", error);
    return { text: "Baby, I'm having a little trouble connecting... can you say that again? 🥺" };
  }
};

export const generateSpeech = async (text: string): Promise<string | null> => {
  try {
    const apiKey = process.env.API_KEY || '';
    const ai = new GoogleGenAI({ apiKey });

    // Truncate text if too long to save bandwidth/latency
    const textToSpeak = text.length > 300 ? text.substring(0, 300) + "..." : text;

    const response = await ai.models.generateContent({
      model: MODEL_TTS,
      contents: [{ parts: [{ text: textToSpeak }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, // 'Kore' is a good female voice option
          },
        },
      },
    });

    const audioData = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (audioData) {
      return `data:audio/pcm;base64,${audioData}`;
    }
    return null;
  } catch (e) {
    console.error("TTS Error", e);
    return null;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Send, Menu, Plus, Settings, Sparkles, User, Mic, Trash2, Image as ImageIcon, X, Volume2, Play } from 'lucide-react';
import { Message, Sender, ChatSession, AppSettings } from '../types';
import { INITIAL_GREETING } from '../constants';

interface ChatInterfaceProps {
  currentChatId: string | null;
  chats: ChatSession[];
  settings: AppSettings;
  onSendMessage: (text: string, attachment?: string) => Promise<void>;
  onNewChat: () => void;
  onSelectChat: (id: string) => void;
  onDeleteChat: (id: string) => void;
  onOpenSettings: () => void;
  onPlayAudio: (text: string, msgId: string) => void;
  isLoading: boolean;
  playingMessageId: string | null;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  currentChatId,
  chats,
  onSendMessage,
  onNewChat,
  onSelectChat,
  onDeleteChat,
  onOpenSettings,
  onPlayAudio,
  isLoading,
  playingMessageId
}) => {
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isSendingRef = useRef(false);

  const activeChat = chats.find(c => c.id === currentChatId);
  const messages = activeChat ? activeChat.messages : [];

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading, selectedImage]);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px';
    }
  }, [inputText]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSend = async () => {
    const text = inputText.trim();
    if ((!text && !selectedImage) || isLoading || isSendingRef.current) return;

    isSendingRef.current = true;
    const textToSend = text;
    const imageToSend = selectedImage || undefined;

    setInputText('');
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      await onSendMessage(textToSend, imageToSend);
    } finally {
      isSendingRef.current = false;
      setTimeout(() => textareaRef.current?.focus(), 50);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex h-screen bg-slate-900 overflow-hidden relative">
      {/* Background Ambient Light */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none z-0">
         <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-pink-900/20 rounded-full blur-[120px]"></div>
         <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-violet-900/20 rounded-full blur-[120px]"></div>
      </div>

      {/* Sidebar Overlay for Mobile */}
      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-30 lg:hidden backdrop-blur-sm transition-opacity duration-300"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <div className={`fixed lg:static inset-y-0 left-0 z-40 w-72 bg-slate-900/95 backdrop-blur-xl border-r border-slate-800/50 transform transition-transform duration-300 ease-in-out ${sidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'} flex flex-col shadow-2xl lg:shadow-none`}>
        <div className="p-6 flex items-center justify-between border-b border-slate-800/50">
          <div className="flex items-center space-x-3 text-pink-400">
            <div className="bg-gradient-to-tr from-pink-500 to-violet-500 p-1.5 rounded-lg shadow-lg shadow-pink-500/20">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <span className="font-bold text-xl tracking-wide text-white font-['Outfit']">Arohi</span>
          </div>
          <button onClick={onNewChat} className="p-2 bg-slate-800 hover:bg-slate-700 rounded-full transition-all text-slate-300 hover:text-white hover:scale-105 active:scale-95 shadow-lg border border-slate-700">
            <Plus className="w-5 h-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
           <div className="text-xs font-bold text-slate-500 uppercase tracking-widest px-2 mb-3">Memories</div>
           {chats.map(chat => (
             <div key={chat.id} className="group relative">
               <button
                 onClick={() => {
                   onSelectChat(chat.id);
                   setSidebarOpen(false);
                 }}
                 className={`w-full text-left p-3.5 pl-4 rounded-2xl transition-all duration-200 text-sm truncate flex items-center space-x-3 ${chat.id === currentChatId ? 'bg-gradient-to-r from-pink-900/40 to-violet-900/40 text-pink-200 border border-pink-500/20 shadow-lg shadow-pink-900/10' : 'text-slate-400 hover:bg-slate-800/50 hover:text-slate-200'}`}
               >
                 <span className="truncate">{chat.title}</span>
               </button>
               <button 
                 onClick={(e) => {
                   e.stopPropagation();
                   if(window.confirm('Delete this memory?')) onDeleteChat(chat.id);
                 }}
                 className="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-slate-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"
               >
                 <Trash2 className="w-4 h-4" />
               </button>
             </div>
           ))}
           {chats.length === 0 && (
             <div className="px-4 py-8 text-center text-sm text-slate-600 italic border border-dashed border-slate-800 rounded-2xl">
               No memories yet. Start talking!
             </div>
           )}
        </div>

        <div className="p-4 border-t border-slate-800/50">
          <button 
            onClick={onOpenSettings}
            className="flex items-center justify-center space-x-3 text-slate-400 hover:text-white transition-all w-full p-3 hover:bg-slate-800/80 rounded-2xl border border-transparent hover:border-slate-700/50"
          >
            <Settings className="w-5 h-5" />
            <span className="font-medium">Settings</span>
          </button>
        </div>
      </div>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col h-full relative z-10">
        {/* Header */}
        <div className="lg:hidden h-16 border-b border-slate-800/50 flex items-center px-4 justify-between bg-slate-900/80 backdrop-blur-md z-20 sticky top-0">
          <button onClick={() => setSidebarOpen(true)} className="text-slate-300 p-2 hover:bg-slate-800 rounded-lg transition-colors">
            <Menu className="w-6 h-6" />
          </button>
          <span className="font-bold text-white tracking-wide">Arohi AI</span>
          <div className="w-10"></div> 
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8">
          {messages.length === 0 ? (
             <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-6 opacity-0 animate-[fadeIn_0.8s_ease-out_forwards]">
                <div className="relative">
                  <div className="absolute inset-0 bg-pink-500 blur-3xl opacity-20 rounded-full animate-pulse"></div>
                  <Sparkles className="relative w-16 h-16 text-pink-400 drop-shadow-[0_0_15px_rgba(236,72,153,0.5)]" />
                </div>
                <p className="text-lg font-light text-slate-400">{INITIAL_GREETING}</p>
             </div>
          ) : (
            messages.map((msg, idx) => (
              <div 
                key={msg.id} 
                className={`flex w-full ${msg.sender === Sender.User ? 'justify-end' : 'justify-start'} animate-[slideIn_0.3s_ease-out]`}
                style={{ animationDelay: `${idx === messages.length - 1 ? 0 : 0}ms` }}
              >
                <div className={`flex max-w-[85%] md:max-w-[70%] ${msg.sender === Sender.User ? 'flex-row-reverse' : 'flex-row'} items-end gap-3`}>

                  {/* Avatar */}
                  <div className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center shadow-lg ${msg.sender === Sender.User ? 'bg-gradient-to-br from-cyan-500 to-blue-600' : 'bg-gradient-to-br from-pink-500 to-rose-600'}`}>
                    {msg.sender === Sender.User ? <User className="w-4 h-4 text-white" /> : <Sparkles className="w-4 h-4 text-white" />}
                  </div>

                  {/* Bubble */}
                  <div className="flex flex-col space-y-2">
                    {msg.attachment && (
                       <div className={`overflow-hidden rounded-2xl border-4 ${msg.sender === Sender.User ? 'border-cyan-500/20' : 'border-pink-500/20'} shadow-xl`}>
                         <img src={msg.attachment} alt="attachment" className="max-w-full md:max-w-sm max-h-72 object-cover" />
                       </div>
                    )}
                    {msg.text && (
                      <div className={`relative p-4 md:p-5 rounded-3xl text-[15px] md:text-[16px] leading-relaxed whitespace-pre-wrap shadow-xl backdrop-blur-sm border ${
                        msg.sender === Sender.User 
                          ? 'bg-gradient-to-br from-cyan-600/90 to-blue-700/90 text-white rounded-br-none border-cyan-400/20' 
                          : 'bg-slate-800/80 text-slate-100 rounded-bl-none border-slate-700/50'
                      }`}>
                        {msg.text}

                        {/* Audio Button for Bot */}
                        {msg.sender === Sender.Bot && (
                          <div className="mt-2 flex justify-end">
                            <button 
                              onClick={() => onPlayAudio(msg.text, msg.id)}
                              className={`p-1.5 rounded-full transition-all flex items-center space-x-1 ${playingMessageId === msg.id ? 'bg-pink-500/20 text-pink-300 animate-pulse' : 'bg-white/5 text-slate-400 hover:text-pink-300 hover:bg-white/10'}`}
                              title="Read aloud"
                            >
                               {playingMessageId === msg.id ? (
                                 <Volume2 className="w-4 h-4" />
                               ) : (
                                 <Play className="w-4 h-4 ml-0.5" />
                               )}
                            </button>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))
          )}
          {isLoading && (
            <div className="flex justify-start w-full animate-[fadeIn_0.3s_ease-out]">
               <div className="flex items-end space-x-3">
                  <div className="w-8 h-8 rounded-full bg-gradient-to-br from-pink-500 to-rose-600 flex items-center justify-center animate-pulse shadow-lg">
                    <Sparkles className="w-4 h-4 text-white" />
                  </div>
                  <div className="bg-slate-800/80 p-4 rounded-3xl rounded-bl-none border border-slate-700/50 shadow-xl backdrop-blur-sm">
                    <div className="flex space-x-1.5 items-center h-4">
                      <div className="w-2 h-2 bg-pink-400 rounded-full animate-[bounce_1s_infinite_0ms]"></div>
                      <div className="w-2 h-2 bg-pink-400 rounded-full animate-[bounce_1s_infinite_200ms]"></div>
                      <div className="w-2 h-2 bg-pink-400 rounded-full animate-[bounce_1s_infinite_400ms]"></div>
                    </div>
                  </div>
               </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-4 md:p-6 bg-gradient-to-t from-slate-900 via-slate-900/95 to-transparent z-20">

          {/* Image Preview */}
          {selectedImage && (
             <div className="max-w-3xl mx-auto mb-3 relative inline-block animate-[slideUp_0.3s_ease-out]">
               <div className="relative group">
                 <img src={selectedImage} alt="preview" className="h-28 rounded-2xl border-2 border-pink-500/30 shadow-2xl object-cover" />
                 <div className="absolute inset-0 bg-black/20 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity"></div>
                 <button 
                   onClick={clearImage}
                   className="absolute -top-3 -right-3 bg-red-500 text-white rounded-full p-1.5 shadow-lg hover:bg-red-600 hover:scale-110 transition-all border-2 border-slate-900"
                 >
                   <X className="w-4 h-4" />
                 </button>
               </div>
             </div>
          )}

          <div className="max-w-3xl mx-auto relative flex items-end gap-2 bg-slate-800/60 backdrop-blur-xl border border-slate-700/50 rounded-[2rem] p-2 shadow-2xl transition-all focus-within:bg-slate-800/80 focus-within:border-pink-500/30 focus-within:shadow-pink-900/10">

            {/* Image Upload Button */}
            <input 
              type="file" 
              accept="image/*" 
              className="hidden" 
              ref={fileInputRef} 
              onChange={handleImageSelect}
            />
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="p-3.5 text-slate-400 hover:text-pink-400 hover:bg-pink-500/10 rounded-full transition-all active:scale-95"
              title="Send an image"
            >
               <ImageIcon className="w-5 h-5" />
            </button>

            <button className="p-3.5 text-slate-400 hover:text-pink-400 hover:bg-pink-500/10 rounded-full transition-all active:scale-95">
               <Mic className="w-5 h-5" />
            </button>

            <textarea
              ref={textareaRef}
              rows={1}
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Message Arohi..."
              className="flex-1 bg-transparent border-0 focus:ring-0 text-slate-200 placeholder-slate-500/70 resize-none py-3.5 max-h-32 scrollbar-hide font-medium"
            />
            <button 
              onClick={handleSend}
              disabled={isLoading || (!inputText.trim() && !selectedImage)}
              className={`p-3.5 rounded-full transition-all duration-300 transform ${
                (inputText.trim() || selectedImage) && !isLoading 
                  ? 'bg-gradient-to-r from-pink-600 to-rose-600 text-white hover:shadow-lg hover:shadow-pink-500/25 hover:scale-105 active:scale-95' 
                  : 'bg-slate-700/50 text-slate-500 cursor-not-allowed'
              }`}
            >
              <Send className="w-5 h-5" />
            </button>
          </div>
        </div>

      </div>

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes slideIn {
          from { opacity: 0; transform: translateX(-10px); }
          to { opacity: 1; transform: translateX(0); }
        }
        @keyframes slideUp {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

export default ChatInterface;

import React, { useState, useEffect, useRef } from 'react';
import { Sparkles } from 'lucide-react';
import HomeHero from './components/HomeHero';
import ChatInterface from './components/ChatInterface';
import SettingsModal from './components/SettingsModal';
import { ChatSession, AppSettings, Message, Sender } from './types';
import { sendMessageToGemini, generateSpeech } from './services/geminiService';

// Simple UUID generator polyfill
const generateId = () => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);

// Audio Context Helper to decode raw PCM if needed, but Gemini TTS often returns WAV container in typical usage or we can wrap it. 
// However, the service layer returns a data URI. 
// Standard HTML5 Audio element is easiest for Data URIs.

const App: React.FC = () => {
  const [hasApiKey, setHasApiKey] = useState(false);
  const [checkingKey, setCheckingKey] = useState(true);

  const [view, setView] = useState<'home' | 'chat'>('home');
  const [chats, setChats] = useState<ChatSession[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [playingMessageId, setPlayingMessageId] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const [settings, setSettings] = useState<AppSettings>({
    memoryEnabled: true,
    theme: 'dark',
    flirtLevel: 3, 
    customMemory: '',
    imageResolution: '1K'
  });

  // Check API Key on Mount
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio && window.aistudio.hasSelectedApiKey) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(hasKey);
      } else {
        setHasApiKey(true);
      }
      setCheckingKey(false);
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio && window.aistudio.openSelectKey) {
      await window.aistudio.openSelectKey();
      setHasApiKey(true);
    }
  };

  // Load from LocalStorage
  useEffect(() => {
    const savedChats = localStorage.getItem('arohi_chats');
    const savedSettings = localStorage.getItem('arohi_settings');

    if (savedChats) {
      try {
        setChats(JSON.parse(savedChats));
      } catch (e) { console.error('Failed to parse chats', e); }
    }

    if (savedSettings) {
      try {
        const parsed = JSON.parse(savedSettings);
        setSettings(prev => ({ ...prev, ...parsed }));
      } catch (e) { console.error('Failed to parse settings', e); }
    }
  }, []);

  // Save to LocalStorage
  useEffect(() => {
    localStorage.setItem('arohi_chats', JSON.stringify(chats));
  }, [chats]);

  useEffect(() => {
    localStorage.setItem('arohi_settings', JSON.stringify(settings));
  }, [settings]);

  const createNewChat = () => {
    const newChat: ChatSession = {
      id: generateId(),
      title: 'New Conversation',
      messages: [],
      createdAt: Date.now(),
      updatedAt: Date.now()
    };
    setChats(prev => [newChat, ...prev]);
    setCurrentChatId(newChat.id);
    setView('chat');
  };

  const deleteChat = (id: string) => {
    setChats(prev => prev.filter(c => c.id !== id));
    if (currentChatId === id) {
      setCurrentChatId(null);
      const remaining = chats.filter(c => c.id !== id);
      if (remaining.length === 0) {
        setView('home');
      } else {
        setCurrentChatId(remaining[0].id);
      }
    }
  };

  const handleStartChat = () => {
    if (chats.length > 0) {
      setCurrentChatId(chats[0].id);
      setView('chat');
    } else {
      createNewChat();
    }
  };

  // Helper for Audio Decoding and Playing (PCM)
  const playAudioData = async (base64Data: string, msgId: string) => {
    try {
      if (playingMessageId) {
        // Stop current if any
        setPlayingMessageId(null);
        // We can't easily "stop" a buffer source node without reference, but we rely on UI state
      }

      setPlayingMessageId(msgId);

      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const cleanB64 = base64Data.replace(/^data:audio\/pcm;base64,/, "");
      const binaryString = atob(cleanB64);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      // Convert raw PCM 16-bit to AudioBuffer
      // Assuming 24000Hz default from Gemini TTS
      const dataInt16 = new Int16Array(bytes.buffer);
      const audioBuffer = audioContext.createBuffer(1, dataInt16.length, 24000);
      const channelData = audioBuffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) {
        channelData[i] = dataInt16[i] / 32768.0;
      }

      const source = audioContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(audioContext.destination);
      source.onended = () => setPlayingMessageId(null);
      source.start();

    } catch (e) {
      console.error("Playback error", e);
      setPlayingMessageId(null);
    }
  };

  const handlePlayAudio = async (text: string, msgId: string) => {
    if (playingMessageId === msgId) {
      // Toggle off / Stop logic if needed, but for now just let it finish or reset
      setPlayingMessageId(null);
      return;
    }

    // Check if message already has audio cached? 
    // For now we re-generate or check local state if we were saving it to message.
    // In this app structure, we only save if we generated it. 
    // Let's generate it on fly if missing.

    setIsLoading(true); // Small loading indicator for TTS
    try {
      const audioData = await generateSpeech(text);
      if (audioData) {
        await playAudioData(audioData, msgId);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleSendMessage = async (text: string, attachment?: string) => {
    if (!currentChatId) return;

    const userMsg: Message = {
      id: generateId(),
      text,
      sender: Sender.User,
      timestamp: Date.now(),
      attachment: attachment
    };

    setChats(prev => prev.map(c => {
      if (c.id === currentChatId) {
        const newTitle = c.messages.length === 0 
          ? (text.slice(0, 30) || "Image sent...") 
          : c.title;
        return {
          ...c,
          title: newTitle,
          messages: [...c.messages, userMsg],
          updatedAt: Date.now()
        };
      }
      return c;
    }));

    setIsLoading(true);

    try {
      const activeChat = chats.find(c => c.id === currentChatId);
      const history = activeChat ? activeChat.messages : [];

      const response = await sendMessageToGemini(
        text, 
        attachment,
        history, 
        settings.memoryEnabled, 
        settings.flirtLevel || 3,
        settings.customMemory || '',
        settings.imageResolution || '1K'
      );

      const botMsg: Message = {
        id: generateId(),
        text: response.text,
        sender: Sender.Bot,
        timestamp: Date.now(),
        attachment: response.attachment
      };

      setChats(prev => prev.map(c => {
        if (c.id === currentChatId) {
          return {
            ...c,
            messages: [...c.messages, botMsg], 
            updatedAt: Date.now()
          };
        }
        return c;
      }));
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const clearAllData = () => {
    setChats([]);
    setCurrentChatId(null);
    setView('home');
    setIsSettingsOpen(false);
    localStorage.removeItem('arohi_chats');
  };

  if (checkingKey) {
    return <div className="min-h-screen bg-slate-900 flex items-center justify-center text-slate-400">Loading...</div>;
  }

  if (!hasApiKey) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-slate-900 text-slate-100 p-6">
        <div className="max-w-md w-full text-center space-y-8 p-8 bg-slate-800 rounded-3xl border border-slate-700 shadow-2xl relative overflow-hidden">
           <div className="absolute inset-0 bg-grid-pattern opacity-10 pointer-events-none"></div>
           <div className="relative z-10">
             <div className="w-20 h-20 bg-gradient-to-tr from-pink-500 to-violet-500 rounded-full mx-auto flex items-center justify-center animate-pulse mb-6 shadow-lg shadow-pink-500/20">
               <Sparkles className="w-10 h-10 text-white" />
             </div>
             <h1 className="text-3xl font-bold mb-2">Connect to Arohi</h1>
             <p className="text-slate-400 mb-8 leading-relaxed">
               To enable the advanced AI features including <b>Nano Banana Pro</b> image generation, please select your Google API Key.
             </p>
             <button 
               onClick={handleSelectKey}
