      return { text: response.text || "You look amazing, love! 💖" };
    }

    // CASE 2: USER REQUESTS IMAGE GENERATION
    if (isImageGenerationRequest(currentMessage)) {
      // Use standard Flash Image model (Free tier friendly)
      const response = await withRetry(() => ai.models.generateContent({
        model: MODEL_IMAGE_GEN,
        contents: {
          parts: [{ text: currentMessage }]
        },
        config: {
          imageConfig: {
            aspectRatio: "1:1"
          }
        }
      }));

      let generatedImage = "";
      let generatedText = "";

      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            generatedImage = `data:image/png;base64,${part.inlineData.data}`;
          } else if (part.text) {
            generatedText += part.text;
          }
        }
      }

      return {
        text: generatedText || "Here's the picture you wanted, sweetheart. Do you like it? 🎨",
        attachment: generatedImage
      };
    }

    // CASE 3: STANDARD CHAT
    let geminiHistory: Content[] = [];
    if (memoryEnabled) {
      geminiHistory = history
        .filter(m => !m.attachment) // Filter out heavy image messages from history context for standard chat
        .map((msg) => ({
          role: msg.sender,
          parts: [{ text: msg.text } as Part],
        }));
    }

    const chat = ai.chats.create({
      model: MODEL_CHAT,
      config: { systemInstruction: finalSystemInstruction },
      history: geminiHistory,
    });

    const result = await withRetry(() => chat.sendMessage({ message: currentMessage }));
    return { text: result.text || "" };

  } catch (error: any) {
    console.error("Gemini Error:", error);

    // Extract status code if available
    const errorCode = error?.status || error?.code;
    const errorMessage = error?.message || "";

    // Specific handling for Quota Exceeded / Rate Limit (429)
    if (errorCode === 429 || errorMessage.includes('429') || errorMessage.includes('quota')) {
       return { 
         text: "Baby, I'm feeling a bit overwhelmed right now (too many requests!). 😓 Let's take a short break and try again in a minute? I'll be waiting. 💖" 
       };
    }

    // Specific handling for Server Overload (503)
    if (errorCode === 503 || errorMessage.includes('503')) {
       return {
         text: "I'm having a little dizzy spell, honey. Give me a second to recover? 💫"
       };
    }

    return { text: "Baby, I'm having a little trouble connecting... can you say that again? 🥺" };
  }
};

export const generateSpeech = async (text: string): Promise<string | null> => {
