import { GoogleGenAI, Content, Part, Modality, GenerateContentResponse } from "@google/genai";
import { Message, Sender, GeminiResponse } from "../types";
import { 
  MODEL_CHAT, 
  MODEL_VISION, 
  MODEL_IMAGE_GEN,
  MODEL_TTS,
  BASE_SYSTEM_INSTRUCTION, 
  FLIRT_LEVEL_INSTRUCTIONS, 
  ROLEPLAY_EXAMPLES 
} from "../constants";

// Helper to clean base64 string
const cleanBase64 = (b64: string) => {
  return b64.replace(/^data:(image|audio)\/(png|jpeg|jpg|webp|mp3|wav|pcm);base64,/, "");
};

// Sleep helper for backoff
const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Retry wrapper
async function withRetry<T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    const errorCode = error?.status || error?.code;
    const errorMessage = error?.message || error?.toString() || "";

    const isRateLimit = errorCode === 429 || errorMessage.includes('429') || errorMessage.includes('quota');
    const isServerOverload = errorCode === 503 || errorMessage.includes('503');

    if (retries > 0 && (isRateLimit || isServerOverload)) {
      console.warn(`Gemini API: Retrying operation... Attempts left: ${retries}. Waiting ${delay}ms.`);
      await sleep(delay);
      return withRetry(operation, retries - 1, delay * 2);
    }
    throw error;
  }
}

// Heuristic to detect image generation requests
const isImageGenerationRequest = (text: string): boolean => {
  const lower = text.toLowerCase();
  const triggers = [
    "generate image", "generate an image", "create image", "create an image",
    "draw", "paint", "sketch", "make a picture", "picture of", "image of",
    "illustrate", "show me a"
  ];
  return triggers.some(t => lower.includes(t));
};

export const sendMessageToGemini = async (
  currentMessage: string,
  attachment: string | undefined,
  history: Message[],
  memoryEnabled: boolean,
  flirtLevel: number,
  customMemory: string
): Promise<GeminiResponse> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const flirtInstruction = FLIRT_LEVEL_INSTRUCTIONS[flirtLevel as keyof typeof FLIRT_LEVEL_INSTRUCTIONS] || FLIRT_LEVEL_INSTRUCTIONS[3];
    const finalSystemInstruction = `
      ${BASE_SYSTEM_INSTRUCTION}
      CURRENT SETTINGS: ${flirtInstruction}
      USER'S CUSTOM MEMORY: ${customMemory ? `"${customMemory}"` : "None."}
      ${ROLEPLAY_EXAMPLES}
    `;

    if (attachment) {
      // Fix: Added GenerateContentResponse type to withRetry to solve 'unknown' type error on line 84
      const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
        model: MODEL_VISION,
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: cleanBase64(attachment) } },
            { text: currentMessage || "What do you see in this photo, baby?" }
          ]
        },
        config: {
          systemInstruction: finalSystemInstruction
        }
      }));
      return { text: response.text || "You look amazing, love! 💖" };
    }

    if (isImageGenerationRequest(currentMessage)) {
      // Fix: Added GenerateContentResponse type to withRetry to solve 'unknown' type error on line 103
      const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
        model: MODEL_IMAGE_GEN,
        contents: {
          parts: [{ text: currentMessage }]
        },
        config: {
          imageConfig: {
            aspectRatio: "1:1"
          }
        }
      }));

      let generatedImage = "";
      let generatedText = "";

      // Fix: Access candidates properties safely now that response is typed
      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            generatedImage = `data:image/png;base64,${part.inlineData.data}`;
          } else if (part.text) {
            generatedText += part.text;
          }
        }
      }

      return {
        text: generatedText || "Here's the picture you wanted, sweetheart. Do you like it? 🎨",
        attachment: generatedImage
      };
    }

    let geminiHistory: Content[] = [];
    if (memoryEnabled) {
      geminiHistory = history
        .filter(m => !m.attachment)
        .map((msg) => ({
          role: msg.sender,
          parts: [{ text: msg.text } as Part],
        }));
    }

    const chat = ai.chats.create({
      model: MODEL_CHAT,
      config: { systemInstruction: finalSystemInstruction },
      history: geminiHistory,
    });

    // Fix: Added GenerateContentResponse type to withRetry to solve 'unknown' type error on line 136
    const result = await withRetry<GenerateContentResponse>(() => chat.sendMessage({ message: currentMessage }));
    return { text: result.text || "" };

  } catch (error: any) {
    console.error("Gemini Error:", error);

    const errorCode = error?.status || error?.code;
    const errorMessage = error?.message || "";

    if (errorCode === 429 || errorMessage.includes('429') || errorMessage.includes('quota')) {
       return { 
         text: "Baby, I'm feeling a bit overwhelmed right now (too many requests!). 😓 Let's take a short break and try again in a minute? I'll be waiting. 💖" 
       };
    }

    if (errorCode === 503 || errorMessage.includes('503')) {
       return {
         text: "I'm having a little dizzy spell, honey. Give me a second to recover? 💫"
       };
    }

    return { text: "Baby, I'm having a little trouble connecting... can you say that again? 🥺" };
  }
};

export const generateSpeech = async (text: string): Promise<string | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const textToSpeak = text.length > 300 ? text.substring(0, 300) + "..." : text;

    // Fix: Added GenerateContentResponse type to withRetry to solve 'unknown' type error on line 178
    const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: MODEL_TTS,
      contents: [{ parts: [{ text: textToSpeak }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, 
          },
        },
      },
    }));

    // Fix: Access candidates properties safely now that response is typed
    const audioData = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (audioData) {
      return `data:audio/pcm;base64,${audioData}`;
    }
    return null;
  } catch (e: any) {
    console.error("TTS Error", e);
    return null;
  }
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Send, Menu, Plus, Settings, Sparkles, User, Mic, Trash2, Image as ImageIcon, X, Volume2, Play, History } from 'lucide-react';
import { Message, Sender, ChatSession, AppSettings } from '../types';
import { INITIAL_GREETING } from '../constants';

interface ChatInterfaceProps {
  currentChatId: string | null;
  chats: ChatSession[];
  settings: AppSettings;
  onSendMessage: (text: string, attachment?: string) => Promise<void>;
  onNewChat: () => void;
  onSelectChat: (id: string) => void;
  onDeleteChat: (id: string) => void;
  onOpenSettings: () => void;
  onPlayAudio: (text: string, msgId: string) => void;
  isLoading: boolean;
  playingMessageId: string | null;
}

const PAGE_SIZE = 20;

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  currentChatId,
  chats,
  onSendMessage,
  onNewChat,
  onSelectChat,
  onDeleteChat,
  onOpenSettings,
  onPlayAudio,
  isLoading,
  playingMessageId
}) => {
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [displayLimit, setDisplayLimit] = useState(PAGE_SIZE);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isSendingRef = useRef(false);

  const activeChat = chats.find(c => c.id === currentChatId);
  const allMessages = activeChat ? activeChat.messages : [];

  // Reset display limit when switching chats
  useEffect(() => {
    setDisplayLimit(PAGE_SIZE);
  }, [currentChatId]);

  // Paginated messages: take only the last 'displayLimit' items
  const visibleMessages = useMemo(() => {
    return allMessages.slice(-displayLimit);
  }, [allMessages, displayLimit]);

  const hasMore = allMessages.length > displayLimit;
  const remainingCount = allMessages.length - displayLimit;

  const handleLoadMore = () => {
    setDisplayLimit(prev => prev + PAGE_SIZE);
  };

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    messagesEndRef.current?.scrollIntoView({ behavior });
  };

  // Scroll to bottom when a NEW message arrives or loading state changes
  useEffect(() => {
    // We only want to auto-scroll to bottom if the last message is new
    // or if we're currently waiting for a response.
    // If the user is loading older messages, we should probably stay put, 
    // but the simple implementation is to scroll if the message count increased from the bottom.
    if (allMessages.length > 0 && !hasMore) {
       scrollToBottom('smooth');
    }
  }, [allMessages.length, isLoading, selectedImage]);

  // Initial scroll to bottom on chat load
  useEffect(() => {
    if (currentChatId) {
      setTimeout(() => scrollToBottom('auto'), 100);
    }
  }, [currentChatId]);

  // Auto-resize textarea
  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px';
    }
  }, [inputText]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSend = async () => {
    const text = inputText.trim();
    if ((!text && !selectedImage) || isLoading || isSendingRef.current) return;

    isSendingRef.current = true;
    const textToSend = text;
    const imageToSend = selectedImage || undefined;

    setInputText('');
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      await onSendMessage(textToSend, imageToSend);
    } finally {
      isSendingRef.current = false;
      setTimeout(() => textareaRef.current?.focus(), 50);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex h-screen bg-slate-900 overflow-hidden relative">
      {/* Background Ambient Light */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none z-0">
         <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-pink-900/20 rounded-full blur-[120px]"></div>
         <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-violet-900/20 rounded-full blur-[120px]"></div>
      </div>

