                        )}
                        {msg.text && (
                          <div className={`relative p-4 md:p-5 rounded-3xl text-[15px] md:text-[16px] leading-relaxed whitespace-pre-wrap shadow-xl backdrop-blur-sm border transition-all duration-300 group-hover/msg:scale-[1.01] ${
                            isUser 
                              ? 'bg-gradient-to-br from-cyan-600/90 to-blue-700/90 text-white rounded-br-none border-cyan-400/20 shadow-cyan-900/10' 
                              : 'bg-slate-800/80 text-slate-100 rounded-bl-none border-slate-700/50 shadow-slate-950/20'
                          }`}>
                            {msg.text}

                            {/* Audio Button for Bot */}
                            {msg.sender === Sender.Bot && (
                              <div className="mt-2 flex justify-end">
                                <button 
                                  onClick={() => onPlayAudio(msg.text, msg.id)}
