                                  title="Read aloud"
                                >
                                  {playingMessageId === msg.id ? (
                                    <Volume2 className="w-4 h-4" />
                                  ) : (
                                    <Play className="w-4 h-4 ml-0.5" />
                                  )}
                                </button>
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </>
          )}
          {isLoading && (
            <div className="flex justify-start w-full animate-messageInLeft">
