                    <div className="w-20 h-20 rounded-full bg-gradient-to-tr from-pink-500 to-violet-600 flex items-center justify-center shadow-2xl animate-pulse">
                        <Lock className="w-8 h-8 text-white" />
                    </div>
                </div>
                <h2 className="text-2xl font-bold text-white mb-2">Arohi is Locked</h2>
                <div className="flex space-x-6 mb-12">
                    {[0, 1, 2, 3].map(i => (
                        <div key={i} className={`w-4 h-4 rounded-full border-2 transition-all ${pin.length > i ? 'bg-pink-500 border-pink-500 scale-125 shadow-[0_0_10px_pink]' : 'border-slate-700'}`} />
                    ))}
                </div>
                <div className="grid grid-cols-3 gap-6 w-full">
                    {[1, 2, 3, 4, 5, 6, 7, 8, 9, '', 0, 'del'].map((num, i) => (
                        <button key={i} onClick={() => num === 'del' ? setPin(pin.slice(0, -1)) : num !== '' && handleNumberClick(num.toString())} className="w-full aspect-square rounded-full bg-slate-900/50 border border-slate-800 text-2xl text-slate-200 flex items-center justify-center active:scale-90 transition-all hover:bg-slate-800">
                            {num === 'del' ? <Delete /> : num}
                        </button>
                    ))}
                </div>
            </div>
        </div>
    );
};

