    const [isLocked, setIsLocked] = useState(false);
    const [isSettingsOpen, setIsSettingsOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [playingMessageId, setPlayingMessageId] = useState<string | null>(null);
    const [displayLimit, setDisplayLimit] = useState(PAGE_SIZE);
    const [settings, setSettings] = useState<AppSettings>({ flirtLevel: 3, passcode: undefined });

    const messagesEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const savedChats = localStorage.getItem('arohi_chats');
        const savedSettings = localStorage.getItem('arohi_settings');
        if (savedChats) setChats(JSON.parse(savedChats));
        if (savedSettings) {
            const s = JSON.parse(savedSettings);
            setSettings(s);
            if (s.passcode) setIsLocked(true);
        }
    }, []);

    useEffect(() => {
        localStorage.setItem('arohi_chats', JSON.stringify(chats));
        localStorage.setItem('arohi_settings', JSON.stringify(settings));
    }, [chats, settings]);

    const activeChat = useMemo(() => chats.find(c => c.id === currentChatId), [chats, currentChatId]);
    const visibleMessages = useMemo(() => activeChat ? activeChat.messages.slice(-displayLimit) : [], [activeChat, displayLimit]);
    const hasMore = (activeChat?.messages.length || 0) > displayLimit;

    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [visibleMessages, isLoading]);

    const onSendMessage = async (text: string, attachment?: string) => {
        if (!currentChatId) return;
        const userMsg: Message = { id: generateId(), text, sender: 'user', timestamp: Date.now(), attachment };

        setChats(prev => prev.map(c => c.id === currentChatId ? {
            ...c, title: c.messages.length === 0 ? (text.slice(0, 20) || "Photo Story") : c.title,
            messages: [...c.messages, userMsg], updatedAt: Date.now()
        } : c));

        setIsLoading(true);
        try {
            const ai = new GoogleGenAI({ apiKey: (process as any).env.API_KEY });
            const sys = `${BASE_SYSTEM_INSTRUCTION} \n Current Mood: ${FLIRT_LEVEL_INSTRUCTIONS[settings.flirtLevel]}`;

            let result;
            if (attachment) {
                result = await ai.models.generateContent({
                    model: MODEL_VISION,
                    contents: { parts: [{ inlineData: { mimeType: 'image/jpeg', data: cleanBase64(attachment) } }, { text: text || "Photo nodi heli nan muddu" }] },
                    config: { systemInstruction: sys }
                });
            } else {
                const chat = ai.chats.create({ model: MODEL_CHAT, config: { systemInstruction: sys } });
                result = await chat.sendMessage({ message: text });
            }

            const botMsg: Message = { id: generateId(), text: result.text || "...", sender: 'model', timestamp: Date.now() };
            setChats(prev => prev.map(c => c.id === currentChatId ? { ...c, messages: [...c.messages, botMsg] } : c));
        } catch (e) {
            console.error(e);
        } finally { setIsLoading(false); }
    };

    const handlePlayAudio = async (text: string, id: string) => {
        setPlayingMessageId(id);
        try {
            const ai = new GoogleGenAI({ apiKey: (process as any).env.API_KEY });
            const res = await ai.models.generateContent({
                model: MODEL_TTS,
                contents: [{ parts: [{ text }] }],
                config: { responseModalities: [Modality.AUDIO] }
            });
            const data = res.candidates[0].content.parts[0].inlineData.data;
            const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
            const buf = await ctx.decodeAudioData(Uint8Array.from(atob(data), c => c.charCodeAt(0)).buffer);
            const src = ctx.createBufferSource();
            src.buffer = buf; src.connect(ctx.destination);
            src.onended = () => setPlayingMessageId(null);
            src.start();
        } catch (e) { 
            console.error(e);
            setPlayingMessageId(null); 
        }
