import React, { useState, useEffect, useRef } from 'react';
import HomeHero from './components/HomeHero';
import ChatInterface from './components/ChatInterface';
import SettingsModal from './components/SettingsModal';
import LockScreen from './components/LockScreen';
import { ChatSession, AppSettings, Message, Sender } from './types';
import { sendMessageToGemini, generateSpeech } from './services/geminiService';

// Simple UUID generator polyfill
const generateId = () => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [view, setView] = useState<'home' | 'chat'>('home');
  const [chats, setChats] = useState<ChatSession[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [playingMessageId, setPlayingMessageId] = useState<string | null>(null);
  const [isLocked, setIsLocked] = useState(false);

  const [settings, setSettings] = useState<AppSettings>({
    memoryEnabled: true,
    theme: 'dark',
    flirtLevel: 3, 
    personaMode: 'romantic',
    customMemory: ''
  });

  // Load from LocalStorage
  useEffect(() => {
    const savedChats = localStorage.getItem('arohi_chats');
    const savedSettings = localStorage.getItem('arohi_settings');

    if (savedChats) {
      try {
        setChats(JSON.parse(savedChats));
      } catch (e) { console.error('Failed to parse chats', e); }
    }

    if (savedSettings) {
      try {
        const parsed = JSON.parse(savedSettings);
        setSettings(prev => ({ 
          ...prev, 
          ...parsed,
          personaMode: parsed.personaMode || 'romantic' // Fallback for old sessions
        }));
        // Lock the app if a passcode exists
        if (parsed.passcode) {
          setIsLocked(true);
        }
      } catch (e) { console.error('Failed to parse settings', e); }
    }
  }, []);

  // Save to LocalStorage
  useEffect(() => {
    if (chats.length > 0) {
      localStorage.setItem('arohi_chats', JSON.stringify(chats));
    } else {
      localStorage.removeItem('arohi_chats');
    }
  }, [chats]);

  useEffect(() => {
    localStorage.setItem('arohi_settings', JSON.stringify(settings));
  }, [settings]);

  const createNewChat = () => {
    const newChat: ChatSession = {
      id: generateId(),
      title: 'New Conversation',
      messages: [],
      createdAt: Date.now(),
      updatedAt: Date.now()
    };
    setChats(prev => [newChat, ...prev]);
    setCurrentChatId(newChat.id);
    setView('chat');
  };

  const deleteChat = (id: string) => {
    const updatedChats = chats.filter(c => c.id !== id);
    setChats(updatedChats);

    // If we are deleting the current chat, handle navigation
    if (currentChatId === id) {
      if (updatedChats.length === 0) {
        setView('home');
        setCurrentChatId(null);
      } else {
        setCurrentChatId(updatedChats[0].id);
      }
    }
  };

  const handleStartChat = () => {
    if (chats.length > 0) {
      setCurrentChatId(chats[0].id);
      setView('chat');
    } else {
      createNewChat();
    }
  };

  // Helper for Audio Decoding and Playing (PCM)
  const playAudioData = async (base64Data: string, msgId: string) => {
    try {
      if (playingMessageId) {
        setPlayingMessageId(null);
      }

      setPlayingMessageId(msgId);

      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const cleanB64 = base64Data.replace(/^data:audio\/pcm;base64,/, "");
      const binaryString = atob(cleanB64);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      const dataInt16 = new Int16Array(bytes.buffer);
      const audioBuffer = audioContext.createBuffer(1, dataInt16.length, 24000);
      const channelData = audioBuffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) {
        channelData[i] = dataInt16[i] / 32768.0;
      }

      const source = audioContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(audioContext.destination);
      source.onended = () => setPlayingMessageId(null);
      source.start();

    } catch (e) {
      console.error("Playback error", e);
      setPlayingMessageId(null);
    }
  };

  const handlePlayAudio = async (text: string, msgId: string) => {
    if (playingMessageId === msgId) {
      setPlayingMessageId(null);
      return;
    }

    setIsLoading(true); 
    try {
      const audioData = await generateSpeech(text);
      if (audioData) {
        await playAudioData(audioData, msgId);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleSendMessage = async (text: string, attachment?: string) => {
    if (!currentChatId) return;

    const userMsg: Message = {
      id: generateId(),
      text,
      sender: Sender.User,
      timestamp: Date.now(),
      attachment: attachment
    };

    setChats(prev => prev.map(c => {
      if (c.id === currentChatId) {
        const newTitle = c.messages.length === 0 
          ? (text.slice(0, 30) || "Image sent...") 
          : c.title;
        return {
          ...c,
          title: newTitle,
          messages: [...c.messages, userMsg],
          updatedAt: Date.now()
        };
      }
      return c;
    }));

    setIsLoading(true);

    try {
      const activeChat = chats.find(c => c.id === currentChatId);
      const history = activeChat ? activeChat.messages : [];

      const response = await sendMessageToGemini(
        text, 
        attachment,
        history, 
        settings.memoryEnabled, 
        settings.flirtLevel || 3,
        settings.customMemory || '',
        settings.personaMode
      );

      const botMsg: Message = {
        id: generateId(),
        text: response.text,
        sender: Sender.Bot,
        timestamp: Date.now(),
        attachment: response.attachment
      };

      setChats(prev => prev.map(c => {
        if (c.id === currentChatId) {
          return {
            ...c,
            messages: [...c.messages, botMsg], 
            updatedAt: Date.now()
          };
        }
        return c;
      }));
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const clearAllData = () => {
    setChats([]);
    setCurrentChatId(null);
    setView('home');
    setIsSettingsOpen(false);
    localStorage.removeItem('arohi_chats');
    localStorage.removeItem('arohi_settings');
    setSettings({
      memoryEnabled: true,
      theme: 'dark',
      flirtLevel: 3, 
      personaMode: 'romantic',
      customMemory: ''
    });
  };

  return (
    <div className="font-sans text-slate-200">
      {isLocked && settings.passcode && (
        <LockScreen 
          storedPin={settings.passcode} 
          onUnlock={() => setIsLocked(false)} 
        />
      )}

      {view === 'home' ? (
        <HomeHero onStartChat={handleStartChat} />
      ) : (
        <ChatInterface 
          currentChatId={currentChatId}
          chats={chats}
          settings={settings}
          onSendMessage={handleSendMessage}
          onNewChat={createNewChat}
          onSelectChat={setCurrentChatId}
          onDeleteChat={deleteChat}
          onOpenSettings={() => setIsSettingsOpen(true)}
          onPlayAudio={handlePlayAudio}
          isLoading={isLoading}
          playingMessageId={playingMessageId}
        />
      )}

      <SettingsModal 
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        onUpdateSettings={setSettings}
        onClearAllData={clearAllData}
      />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Send, Menu, Plus, Settings, Sparkles, User, Mic, Trash2, Image as ImageIcon, X, Volume2, Play, History, Loader2, Heart, Share2, MoreHorizontal } from 'lucide-react';
import { Message, Sender, ChatSession, AppSettings } from '../types';
import { INITIAL_GREETING } from '../constants';

interface ChatInterfaceProps {
  currentChatId: string | null;
  chats: ChatSession[];
  settings: AppSettings;
  onSendMessage: (text: string, attachment?: string) => Promise<void>;
  onNewChat: () => void;
  onSelectChat: (id: string) => void;
  onDeleteChat: (id: string) => void;
  onOpenSettings: () => void;
  onPlayAudio: (text: string, msgId: string) => void;
  isLoading: boolean;
  playingMessageId: string | null;
}

const PAGE_SIZE = 20;

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  currentChatId,
  chats,
  onSendMessage,
  onNewChat,
  onSelectChat,
  onDeleteChat,
  onOpenSettings,
  onPlayAudio,
  isLoading,
  playingMessageId
}) => {
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [displayLimit, setDisplayLimit] = useState(PAGE_SIZE);
  const [localIsSending, setLocalIsSending] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messageContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const activeChat = chats.find(c => c.id === currentChatId);
  const allMessages = activeChat ? activeChat.messages : [];

  // Refined Send Logic: Enabled ONLY when there's content AND bot isn't busy
  const hasContent = inputText.trim().length > 0 || selectedImage !== null;
  const canSend = hasContent && !isLoading && !localIsSending;

  useEffect(() => {
    setDisplayLimit(PAGE_SIZE);
  }, [currentChatId]);

  const visibleMessages = useMemo(() => {
    return allMessages.slice(-displayLimit);
  }, [allMessages, displayLimit]);

  const hasMore = allMessages.length > displayLimit;
  const remainingCount = allMessages.length - displayLimit;

  const handleLoadMore = () => {
    setDisplayLimit(prev => prev + PAGE_SIZE);
  };

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior });
    }
  };

  useEffect(() => {
    if (allMessages.length > 0) {
       scrollToBottom('smooth');
    }
  }, [allMessages.length, isLoading, selectedImage]);

  useEffect(() => {
    if (currentChatId) {
      setTimeout(() => scrollToBottom('auto'), 50);
    }
  }, [currentChatId]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px';
    }
  }, [inputText]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
