                    <div className="flex space-x-2 items-center">
                      <div className="w-2 h-2 bg-pink-500 rounded-full animate-[bounce_1s_infinite_0ms]"></div>
                      <div className="w-2 h-2 bg-pink-500 rounded-full animate-[bounce_1s_infinite_200ms]"></div>
                      <div className="w-2 h-2 bg-pink-500 rounded-full animate-[bounce_1s_infinite_400ms]"></div>
                    </div>
                  </div>
               </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-4 md:p-8 bg-gradient-to-t from-[#020617] via-[#020617]/95 to-transparent">
          <div className="max-w-4xl mx-auto">
            {selectedImage && (
               <div className="mb-4 relative inline-block animate-[messageInLeft_0.4s_ease-out]">
                 <div className="relative group">
                   <img src={selectedImage} alt="preview" className="h-32 rounded-3xl border border-pink-500/40 shadow-2xl object-cover transition-transform duration-500 group-hover:scale-105" />
                   <button 
                     onClick={clearImage}
                     className="absolute -top-3 -right-3 bg-red-500 text-white rounded-full p-2 shadow-2xl hover:bg-red-600 hover:scale-110 transition-all border-4 border-[#020617]"
                   >
                     <X className="w-4 h-4" />
                   </button>
                 </div>
               </div>
            )}

            <div className="relative flex items-end gap-3 glass border-white/10 rounded-[2.5rem] p-3 shadow-2xl transition-all duration-500 focus-within:bg-[#0f172a]/80 focus-within:border-pink-500/40 group/input">
              <input 
                type="file" 
                accept="image/*" 
                className="hidden" 
                ref={fileInputRef} 
                onChange={handleImageSelect}
              />
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-4 text-slate-400 hover:text-pink-400 hover:bg-pink-500/10 rounded-[1.5rem] transition-all active:scale-90"
              >
                 <ImageIcon className="w-6 h-6" />
              </button>

              <button className="p-4 text-slate-400 hover:text-pink-400 hover:bg-pink-500/10 rounded-[1.5rem] transition-all active:scale-90">
                 <Mic className="w-6 h-6" />
              </button>

              <textarea
                ref={textareaRef}
                rows={1}
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Talk to Arohi..."
                className="flex-1 bg-transparent border-0 focus:ring-0 text-white placeholder-slate-600 resize-none py-4 text-lg font-medium scrollbar-hide"
              />
              <button 
                onClick={handleSend}
                disabled={!canSend}
                className={`p-4 rounded-[1.5rem] transition-all duration-500 transform flex items-center justify-center min-w-[60px] min-h-[60px] ${
                  (hasContent && !isLoading) 
                    ? 'premium-gradient text-white shadow-xl shadow-pink-500/20 hover:scale-110 active:scale-90' 
                    : 'bg-white/5 text-slate-600 cursor-not-allowed'
                } ${(isLoading || localIsSending) ? 'opacity-70' : ''}`}
              >
                {(isLoading || localIsSending) ? (
                  <Loader2 className="w-6 h-6 animate-spin" />
                ) : (
                  <Send className="w-6 h-6" />
                )}
              </button>
            </div>
            <div className="mt-4 text-[9px] text-center font-black uppercase tracking-[0.4em] text-slate-700">Arohi • End-to-End Encryption</div>
          </div>
        </div>
      </main>

      <style>{`
        @keyframes messageIn { 
          from { opacity: 0; transform: translateY(20px) scale(0.98); } 
          to { opacity: 1; transform: translateY(0) scale(1); } 
        }
        @keyframes bounce { 
          0%, 100% { transform: translateY(0); } 
          50% { transform: translateY(-5px); } 
        }
        .scrollbar-hide::-webkit-scrollbar { display: none; }
        .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

