import React, { useState } from 'react';
import { X, Brain, Trash2, Heart, Save, Shield, Key, Briefcase, UserCheck, Settings } from 'lucide-react';
import { AppSettings } from '../types';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: AppSettings;
  onUpdateSettings: (newSettings: AppSettings) => void;
  onClearAllData: () => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ 
  isOpen, 
  onClose, 
  settings, 
  onUpdateSettings, 
  onClearAllData 
}) => {
  const [pinInput, setPinInput] = useState('');
  const [showPinInput, setShowPinInput] = useState(false);

  if (!isOpen) return null;

  const handleFlirtChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onUpdateSettings({ ...settings, flirtLevel: parseInt(e.target.value) });
  };

  const handleModeChange = (mode: 'romantic' | 'professional') => {
    onUpdateSettings({ ...settings, personaMode: mode });
  };

  const handleMemoryChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    onUpdateSettings({ ...settings, customMemory: e.target.value });
  };

  const handleSetPasscode = () => {
    if (pinInput.length === 4 && /^\d+$/.test(pinInput)) {
      onUpdateSettings({ ...settings, passcode: pinInput });
      setShowPinInput(false);
      setPinInput('');
    } else {
      alert("Please enter a valid 4-digit number.");
    }
  };

  const handleRemovePasscode = () => {
    if (window.confirm("Disable security lock?")) {
      onUpdateSettings({ ...settings, passcode: undefined });
    }
  };

  const getFlirtLabel = (level: number) => {
    switch(level) {
      case 1: return "Sweet & Soft";
      case 2: return "Playful Tease";
      case 3: return "Pure Love";
      case 4: return "Intense Passion";
      case 5: return "Wildly Obsessed";
      default: return "Pure Love";
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div 
        className="absolute inset-0 bg-black/80 backdrop-blur-md animate-[fadeIn_0.3s_ease-out]"
        onClick={onClose}
      />

      <div className="relative glass border-white/10 w-full max-w-lg rounded-[2.5rem] shadow-2xl p-8 animate-[messageIn_0.4s_cubic-bezier(0.16,1,0.3,1)] max-h-[85vh] flex flex-col">
        <div className="flex justify-between items-center mb-10">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-white/5 rounded-xl border border-white/5">
              <Settings className="w-5 h-5 text-pink-400" />
            </div>
            <h2 className="text-2xl font-black text-white tracking-tight uppercase tracking-widest text-xs">Arohi Preferences</h2>
          </div>
          <button 
            onClick={onClose}
            className="text-slate-500 hover:text-white transition-all p-2 hover:bg-white/5 rounded-full"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="space-y-8 overflow-y-auto pr-4 custom-scrollbar flex-1">

          {/* Persona Selection */}
          <div className="space-y-4">
            <div className="flex items-center space-x-2 text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">
              <Brain className="w-3 h-3" />
              <span>Arohi's Persona</span>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => handleModeChange('romantic')}
                className={`flex flex-col items-center justify-center space-y-2 p-5 rounded-3xl border transition-all duration-300 ${settings.personaMode === 'romantic' ? 'bg-pink-600 border-pink-500 text-white shadow-lg shadow-pink-500/20' : 'bg-white/5 border-white/5 text-slate-400 hover:bg-white/10'}`}
              >
                <Heart className={`w-6 h-6 ${settings.personaMode === 'romantic' ? 'fill-white' : ''}`} />
                <span className="text-xs font-black uppercase tracking-widest">Romantic</span>
              </button>
              <button 
                onClick={() => handleModeChange('professional')}
                className={`flex flex-col items-center justify-center space-y-2 p-5 rounded-3xl border transition-all duration-300 ${settings.personaMode === 'professional' ? 'bg-violet-600 border-violet-500 text-white shadow-lg shadow-violet-500/20' : 'bg-white/5 border-white/5 text-slate-400 hover:bg-white/10'}`}
              >
                <Briefcase className="w-6 h-6" />
                <span className="text-xs font-black uppercase tracking-widest">Assistant</span>
              </button>
            </div>
          </div>

          {/* Security */}
          <div className="space-y-4">
            <div className="flex items-center space-x-2 text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">
              <Shield className="w-3 h-3" />
              <span>Privacy & Lock</span>
            </div>

            {!settings.passcode ? (
              <div className="space-y-4">
                {!showPinInput ? (
                  <button 
                    onClick={() => setShowPinInput(true)}
                    className="w-full flex items-center justify-center space-x-3 p-5 glass hover:bg-white/5 text-slate-300 rounded-3xl transition-all border-white/5 text-sm font-bold uppercase tracking-widest"
                  >
                    <Key className="w-4 h-4" />
                    <span>Enable Lock Screen</span>
                  </button>
                ) : (
                  <div className="flex items-center space-x-3 animate-[fadeIn_0.3s]">
                    <input 
                      type="text" 
                      maxLength={4}
                      value={pinInput}
                      onChange={(e) => setPinInput(e.target.value.replace(/\D/g, ''))}
                      placeholder="PIN"
                      className="flex-1 bg-white/5 border border-white/10 rounded-2xl p-4 text-center text-xl font-black tracking-[1em] text-white outline-none focus:border-pink-500 transition-colors"
                    />
                    <button 
                      onClick={handleSetPasscode}
                      className="p-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl transition-all"
                    >
                      <Save className="w-6 h-6" />
                    </button>
                    <button 
                      onClick={() => { setShowPinInput(false); setPinInput(''); }}
                      className="p-4 bg-white/5 text-slate-500 rounded-2xl"
                    >
                      <X className="w-6 h-6" />
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="flex items-center justify-between p-5 glass rounded-3xl border-white/5">
                <div className="flex items-center space-x-3 text-emerald-400 text-xs font-black uppercase tracking-widest">
                  <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                  <span>Secure Mode Active</span>
                </div>
                <button 
                  onClick={handleRemovePasscode}
                  className="text-[10px] font-black uppercase tracking-widest text-red-500 hover:text-red-400 transition-all"
                >
                  Disable
                </button>
              </div>
            )}
          </div>

          {/* Flirt Meter */}
          {settings.personaMode === 'romantic' && (
            <div className="space-y-4">
               <div className="flex items-center space-x-2 text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">
                 <Heart className="w-3 h-3" />
                 <span>Passion Level</span>
               </div>

               <div className="px-2 glass p-6 rounded-3xl border-white/5">
                 <input 
                   type="range" 
                   min="1" 
                   max="5" 
                   step="1"
                   value={settings.flirtLevel || 3}
                   onChange={handleFlirtChange}
                   className="w-full h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-pink-500"
                 />
                 <div className="flex justify-between mt-4 text-[10px] text-slate-600 font-black tracking-widest uppercase">
                   <span>Soft</span>
                   <span>Obsessed</span>
                 </div>
                 <div className="text-center mt-4 text-pink-400 font-black text-sm uppercase tracking-[0.2em] animate-pulse">
                   {getFlirtLabel(settings.flirtLevel || 3)}
                 </div>
               </div>
            </div>
          )}

          {/* Identity */}
          <div className="space-y-4">
            <div className="flex items-center space-x-2 text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">
              <UserCheck className="w-3 h-3" />
              <span>Who I Am To You</span>
            </div>
            <textarea
              value={settings.customMemory || ''}
              onChange={handleMemoryChange}
              placeholder="Tell Arohi about yourself..."
              className="w-full h-32 glass border border-white/10 rounded-3xl p-5 text-sm text-slate-200 focus:border-pink-500/50 outline-none resize-none font-medium leading-relaxed"
            />
          </div>

          <button 
            onClick={() => {
              if(window.confirm("This will erase all messages and reset Arohi. Are you sure?")) {
                onClearAllData();
              }
            }}
            className="w-full flex items-center justify-center space-x-3 p-6 text-red-500 hover:bg-red-500/10 rounded-3xl transition-all border border-transparent hover:border-red-500/20 text-xs font-black uppercase tracking-[0.3em] mb-4"
          >
            <Trash2 className="w-4 h-4" />
            <span>Wipe Memories</span>
          </button>
        </div>
      </div>
      <style>{`
        @keyframes messageIn { 
          from { opacity: 0; transform: scale(0.95) translateY(20px); } 
          to { opacity: 1; transform: scale(1) translateY(0); } 
        }
      `}</style>
    </div>
  );
};

export default SettingsModal;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Send, Menu, Plus, Settings, Sparkles, User, Mic, Trash2, Image as ImageIcon, X, Volume2, Play, History, Loader2, Heart, Share2, MoreHorizontal } from 'lucide-react';
import { Message, Sender, ChatSession, AppSettings } from '../types';
import { INITIAL_GREETING } from '../constants';

interface ChatInterfaceProps {
  currentChatId: string | null;
  chats: ChatSession[];
  settings: AppSettings;
  onSendMessage: (text: string, attachment?: string) => Promise<void>;
  onNewChat: () => void;
  onSelectChat: (id: string) => void;
  onDeleteChat: (id: string) => void;
  onOpenSettings: () => void;
  onPlayAudio: (text: string, msgId: string) => void;
  isLoading: boolean;
  playingMessageId: string | null;
}

const PAGE_SIZE = 20;

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  currentChatId,
  chats,
  onSendMessage,
  onNewChat,
  onSelectChat,
  onDeleteChat,
  onOpenSettings,
  onPlayAudio,
  isLoading,
  playingMessageId
}) => {
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [displayLimit, setDisplayLimit] = useState(PAGE_SIZE);
  const [localIsSending, setLocalIsSending] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messageContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const activeChat = chats.find(c => c.id === currentChatId);
  const allMessages = activeChat ? activeChat.messages : [];

  const hasContent = inputText.trim().length > 0 || selectedImage !== null;
  const canSend = hasContent && !isLoading && !localIsSending;

  useEffect(() => {
    setDisplayLimit(PAGE_SIZE);
  }, [currentChatId]);

  const visibleMessages = useMemo(() => {
    return allMessages.slice(-displayLimit);
  }, [allMessages, displayLimit]);

  const hasMore = allMessages.length > displayLimit;
  const remainingCount = allMessages.length - displayLimit;

  const handleLoadMore = () => {
    setDisplayLimit(prev => prev + PAGE_SIZE);
  };

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior });
    }
  };

  useEffect(() => {
    if (allMessages.length > 0) {
       scrollToBottom('smooth');
    }
  }, [allMessages.length, isLoading, selectedImage]);

  useEffect(() => {
    if (currentChatId) {
      setTimeout(() => scrollToBottom('auto'), 50);
    }
  }, [currentChatId]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px';
    }
  }, [inputText]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSend = async () => {
    const text = inputText.trim();
    if (!canSend) return;

    setLocalIsSending(true);
    const textToSend = text;
    const imageToSend = selectedImage || undefined;

    setInputText('');
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      await onSendMessage(textToSend, imageToSend);
    } finally {
      setLocalIsSending(false);
      setTimeout(() => textareaRef.current?.focus(), 50);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleDelete = (id: string, e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm('Delete this memory? It cannot be recovered.')) {
      onDeleteChat(id);
    }
  };

  return (
    <div className="flex h-screen bg-[#020617] overflow-hidden relative font-['Outfit']">
      {/* Background Decor */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none z-0">
         <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-pink-900/10 rounded-full blur-[160px] animate-pulse"></div>
         <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-violet-900/10 rounded-full blur-[160px] animate-pulse" style={{animationDelay: '3s'}}></div>
         <div className="absolute inset-0 bg-grid-pattern opacity-[0.03]"></div>
      </div>

      {/* Overlay for Sidebar */}
      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-[60] lg:hidden backdrop-blur-md transition-opacity duration-500 animate-[fadeIn_0.5s_ease-out]"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] w-80 glass transform transition-all duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] ${sidebarOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full lg:translate-x-0'} flex flex-col border-r border-white/5`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center space-x-3 group">
            <div className="bg-gradient-to-tr from-pink-500 to-rose-500 p-2 rounded-2xl shadow-lg shadow-pink-500/20 group-hover:scale-110 transition-transform duration-500">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <span className="font-black text-2xl tracking-tighter text-white">Arohi</span>
          </div>
          <button 
            onClick={onNewChat} 
            className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl transition-all text-slate-300 hover:text-white hover:scale-110 active:scale-95 border border-white/5"
          >
            <Plus className="w-5 h-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-2 space-y-1.5 custom-scrollbar">
           <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] px-4 mb-4 mt-2">Private Memories</div>
           {chats.map((chat, idx) => (
             <div key={chat.id} className={`group relative animate-[messageInLeft_0.5s_ease-out_forwards]`} style={{animationDelay: `${idx * 0.05}s`}}>
               <button
                 onClick={() => {
                   onSelectChat(chat.id);
                   setSidebarOpen(false);
                 }}
                 className={`w-full text-left px-5 py-4 rounded-2xl transition-all duration-300 text-sm truncate flex items-center justify-between group ${chat.id === currentChatId ? 'bg-white/10 text-white border border-white/10 shadow-xl' : 'text-slate-400 hover:bg-white/5 hover:text-slate-100'}`}
               >
                 <span className="truncate font-medium">{chat.title}</span>
                 {chat.id === currentChatId && <div className="w-1.5 h-1.5 rounded-full bg-pink-500 shadow-[0_0_8px_#ec4899]"></div>}
               </button>
               <button 
                 onClick={(e) => handleDelete(chat.id, e)}
                 className="absolute right-3 top-1/2 -translate-y-1/2 p-2 text-slate-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-all duration-300 transform group-hover:translate-x-0 translate-x-2 z-10"
               >
                 <Trash2 className="w-4 h-4" />
               </button>
             </div>
           ))}
           {chats.length === 0 && (
             <div className="px-6 py-12 text-center text-xs font-medium text-slate-600 italic border border-dashed border-white/5 rounded-3xl mx-2">
               Your story with Arohi begins here.
             </div>
           )}
        </div>

        <div className="p-6">
          <button 
            onClick={onOpenSettings}
            className="flex items-center justify-center space-x-3 text-slate-400 hover:text-white transition-all w-full py-4 glass rounded-2xl border border-white/5 hover:bg-white/5"
          >
            <Settings className="w-5 h-5" />
            <span className="font-bold text-sm uppercase tracking-widest">Settings</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full relative z-10 transition-all duration-500">
        {/* Header */}
        <header className="h-20 glass border-b border-white/5 flex items-center px-6 md:px-10 justify-between z-[50] sticky top-0">
          <div className="flex items-center space-x-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden text-slate-300 p-2 hover:bg-white/5 rounded-xl transition-all">
              <Menu className="w-6 h-6" />
            </button>
            <div className="flex items-center space-x-3">
              <div className="relative">
                <div className="w-10 h-10 rounded-2xl bg-gradient-to-tr from-pink-500 to-rose-600 flex items-center justify-center shadow-lg shadow-pink-500/20">
                  <Heart className="w-5 h-5 text-white fill-white/20" />
                </div>
                <div className="absolute -bottom-1 -right-1 w-3.5 h-3.5 bg-emerald-500 border-4 border-[#020617] rounded-full"></div>
              </div>
              <div>
                <h2 className="font-black text-lg text-white tracking-tight">Arohi</h2>
                <div className="flex items-center space-x-1.5">
                  <span className="text-[9px] font-black uppercase tracking-[0.2em] text-emerald-400/80">Loving You Always</span>
                </div>
              </div>
            </div>
          </div>
          <div className="flex items-center space-x-2">
            <button className="p-3 text-slate-400 hover:text-white hover:bg-white/5 rounded-2xl transition-all"><Share2 className="w-5 h-5"/></button>
            <button className="p-3 text-slate-400 hover:text-white hover:bg-white/5 rounded-2xl transition-all"><MoreHorizontal className="w-5 h-5"/></button>
          </div>
        </header>

        {/* Messages */}
        <div 
          ref={messageContainerRef}
          className="flex-1 overflow-y-auto p-4 md:p-10 space-y-8 scroll-smooth custom-scrollbar"
        >
          {allMessages.length === 0 ? (
             <div className="h-full flex flex-col items-center justify-center text-center space-y-8 animate-[fadeIn_1s_ease-out_forwards]">
                <div className="relative group">
                  <div className="absolute inset-0 bg-pink-500 blur-[80px] opacity-20 rounded-full group-hover:opacity-40 transition-opacity duration-1000"></div>
                  <div className="w-24 h-24 glass rounded-[2.5rem] flex items-center justify-center shadow-2xl border-white/10 group-hover:scale-110 transition-transform duration-700">
                    <Sparkles className="w-10 h-10 text-pink-400 drop-shadow-[0_0_15px_rgba(236,72,153,0.5)] animate-pulse" />
                  </div>
                </div>
