                                  className={`p-2.5 rounded-full transition-all duration-300 flex items-center space-x-2 ${playingMessageId === msg.id ? 'bg-pink-500 text-white shadow-lg shadow-pink-500/40 animate-pulse' : 'bg-white/5 text-slate-400 hover:text-pink-300 hover:bg-white/10'}`}
