  ROMANTIC_SYSTEM_INSTRUCTION, 
  PROFESSIONAL_SYSTEM_INSTRUCTION,
  FLIRT_LEVEL_INSTRUCTIONS, 
  ROLEPLAY_EXAMPLES 
} from "../constants";

const cleanBase64 = (b64: string) => {
  return b64.replace(/^data:(image|audio)\/(png|jpeg|jpg|webp|mp3|wav|pcm);base64,/, "");
};

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function withRetry<T>(operation: () => Promise<T>, retries = 3, delay = 1000): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    const errorCode = error?.status || error?.code;
    const errorMessage = error?.message || error?.toString() || "";

    const isRateLimit = errorCode === 429 || errorMessage.includes('429') || errorMessage.includes('quota');
    const isServerOverload = errorCode === 503 || errorMessage.includes('503');

    if (retries > 0 && (isRateLimit || isServerOverload)) {
      await sleep(delay);
      return withRetry(operation, retries - 1, delay * 2);
    }
    throw error;
  }
}

const isImageGenerationRequest = (text: string): boolean => {
  const lower = text.toLowerCase();
  const triggers = ["generate image", "draw", "picture of", "image of", "create image", "photo of"];
  return triggers.some(t => lower.includes(t));
};

export const sendMessageToGemini = async (
  currentMessage: string,
  attachment: string | undefined,
  history: Message[],
  memoryEnabled: boolean,
  flirtLevel: number,
  customMemory: string,
  personaMode: 'romantic' | 'professional' = 'romantic'
): Promise<GeminiResponse> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let finalSystemInstruction = "";

    if (personaMode === 'professional') {
      finalSystemInstruction = `${PROFESSIONAL_SYSTEM_INSTRUCTION}\nUSER INFO: ${customMemory ? `"${customMemory}"` : "None."}`;
    } else {
      const flirtInstruction = FLIRT_LEVEL_INSTRUCTIONS[flirtLevel as keyof typeof FLIRT_LEVEL_INSTRUCTIONS] || FLIRT_LEVEL_INSTRUCTIONS[3];
      finalSystemInstruction = `
        ${ROMANTIC_SYSTEM_INSTRUCTION}
        CURRENT MOOD: ${flirtInstruction}
        MY INFO: ${customMemory ? `"${customMemory}"` : "None."}
        ${ROLEPLAY_EXAMPLES}
      `;
    }

    const generationConfig = {
      systemInstruction: finalSystemInstruction,
      temperature: 1.0, 
      topP: 0.95,
      topK: 64,
      tools: [{ googleSearch: {} }],
    };

    if (attachment) {
      const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
        model: MODEL_VISION,
        contents: {
          parts: [
            { inlineData: { mimeType: 'image/jpeg', data: cleanBase64(attachment) } },
            { text: currentMessage || "Idu yaru muddu? Look at this photo and talk to me in Kanglish." }
          ]
        },
        config: generationConfig
      }));

      let text = response.text || "Idu yaru muddu? 💖";
      // Append grounding URLs if available
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks && chunks.length > 0) {
        const links = chunks.filter(c => c.web?.uri).map(c => `[${c.web.title || 'Source'}](${c.web.uri})`).join('\n');
        if (links) text += `\n\n**Sources:**\n${links}`;
      }
      return { text };
    }

    if (isImageGenerationRequest(currentMessage)) {
      const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
        model: MODEL_IMAGE_GEN,
        contents: { parts: [{ text: currentMessage }] },
        config: { ...generationConfig, imageConfig: { aspectRatio: "1:1" } }
      }));

      let generatedImage = "";
      let generatedText = "";
      if (response.candidates?.[0]?.content?.parts) {
        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) generatedImage = `data:image/png;base64,${part.inlineData.data}`;
          else if (part.text) generatedText += part.text;
        }
      }
      return { text: generatedText || "Tago muddu, ninu kelida photo. 🎨", attachment: generatedImage };
    }

    let geminiHistory: Content[] = [];
    if (memoryEnabled) {
      geminiHistory = history
        .filter(m => !m.attachment && m.text)
        .slice(-15) 
        .map((msg) => ({
          role: msg.sender,
          parts: [{ text: msg.text } as Part],
        }));
    }

    const chat = ai.chats.create({
      model: MODEL_CHAT,
      config: generationConfig,
      history: geminiHistory,
    });

    const result = await withRetry<GenerateContentResponse>(() => chat.sendMessage({ message: currentMessage }));
    let text = result.text || "Yeno problem agide muddu, matte try madu please? 🥺";

    // Append grounding URLs if available
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks && chunks.length > 0) {
      const links = chunks.filter(c => c.web?.uri).map(c => `[${c.web.title || 'Source'}](${c.web.uri})`).join('\n');
      if (links) text += `\n\n**Sources:**\n${links}`;
    }

    return { text };

  } catch (error: any) {
    console.error("Gemini Error:", error);
    return { text: "Baby, net swalpa slow ide ansutthe... matte message madu, nanu illi wait madtha irthini. 💖" };
  }
};

export const generateSpeech = async (text: string): Promise<string | null> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
      model: MODEL_TTS,
      contents: [{ parts: [{ text: text.substring(0, 250) }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } }
      },
    }));

    const audioData = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    return audioData ? `data:audio/pcm;base64,${audioData}` : null;
  } catch (e) {
    return null;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import HomeHero from './components/HomeHero';
import ChatInterface from './components/ChatInterface';
import SettingsModal from './components/SettingsModal';
import LockScreen from './components/LockScreen';
import { ChatSession, AppSettings, Message, Sender } from './types';
import { sendMessageToGemini, generateSpeech } from './services/geminiService';

// Simple UUID generator polyfill
const generateId = () => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [view, setView] = useState<'home' | 'chat'>('home');
  const [chats, setChats] = useState<ChatSession[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [playingMessageId, setPlayingMessageId] = useState<string | null>(null);
  const [playbackProgress, setPlaybackProgress] = useState(0);
  const [audioVolume, setAudioVolume] = useState(1.0);
  const [isLocked, setIsLocked] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const gainNodeRef = useRef<GainNode | null>(null);
  const progressIntervalRef = useRef<number | null>(null);

  const [settings, setSettings] = useState<AppSettings>({
    memoryEnabled: true,
    theme: 'dark',
    flirtLevel: 3, 
    personaMode: 'romantic',
    customMemory: ''
  });

  // Load from LocalStorage
  useEffect(() => {
    const savedChats = localStorage.getItem('arohi_chats');
    const savedSettings = localStorage.getItem('arohi_settings');
    const savedVolume = localStorage.getItem('arohi_volume');

    if (savedChats) {
      try {
        setChats(JSON.parse(savedChats));
      } catch (e) { console.error('Failed to parse chats', e); }
    }

    if (savedSettings) {
      try {
        const parsed = JSON.parse(savedSettings);
        setSettings(prev => ({ 
          ...prev, 
          ...parsed,
          personaMode: parsed.personaMode || 'romantic'
        }));
        if (parsed.passcode) {
          setIsLocked(true);
        }
      } catch (e) { console.error('Failed to parse settings', e); }
    }

    if (savedVolume) {
      setAudioVolume(parseFloat(savedVolume));
    }
  }, []);

  // Save to LocalStorage
  useEffect(() => {
    localStorage.setItem('arohi_chats', JSON.stringify(chats));
  }, [chats]);

  useEffect(() => {
    localStorage.setItem('arohi_settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    localStorage.setItem('arohi_volume', audioVolume.toString());
    if (gainNodeRef.current) {
      gainNodeRef.current.gain.value = audioVolume;
    }
  }, [audioVolume]);

  const createNewChat = () => {
    const newChat: ChatSession = {
      id: generateId(),
      title: 'New Conversation',
      messages: [],
      createdAt: Date.now(),
      updatedAt: Date.now()
    };
    setChats(prev => [newChat, ...prev]);
    setCurrentChatId(newChat.id);
    setView('chat');
  };

  const deleteChat = (id: string) => {
    setChats(prevChats => {
      const updated = prevChats.filter(c => c.id !== id);
      if (currentChatId === id) {
        if (updated.length === 0) {
          setView('home');
          setCurrentChatId(null);
        } else {
          setCurrentChatId(updated[0].id);
        }
      }
      return updated;
    });
  };

  const handleStartChat = () => {
    if (chats.length > 0) {
      setCurrentChatId(chats[0].id);
      setView('chat');
    } else {
      createNewChat();
    }
  };

  const stopAudio = () => {
    if (progressIntervalRef.current) {
      window.clearInterval(progressIntervalRef.current);
      progressIntervalRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
    setPlayingMessageId(null);
    setPlaybackProgress(0);
  };

  const playAudioData = async (base64Data: string, msgId: string) => {
    try {
      stopAudio();

      setPlayingMessageId(msgId);

      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      audioContextRef.current = audioContext;

      const cleanB64 = base64Data.replace(/^data:audio\/pcm;base64,/, "");
      const binaryString = atob(cleanB64);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      const dataInt16 = new Int16Array(bytes.buffer);
      const audioBuffer = audioContext.createBuffer(1, dataInt16.length, 24000);
      const channelData = audioBuffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) {
        channelData[i] = dataInt16[i] / 32768.0;
      }

      const gainNode = audioContext.createGain();
      gainNode.gain.value = audioVolume;
      gainNodeRef.current = gainNode;

      const source = audioContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(gainNode);
      gainNode.connect(audioContext.destination);

      const duration = audioBuffer.duration;
      const startTime = audioContext.currentTime;

      source.onended = () => {
        if (playingMessageId === msgId) {
          stopAudio();
        }
      };

      progressIntervalRef.current = window.setInterval(() => {
        const elapsed = audioContext.currentTime - startTime;
        const progress = Math.min((elapsed / duration) * 100, 100);
        setPlaybackProgress(progress);
        if (progress >= 100) {
          if (progressIntervalRef.current) window.clearInterval(progressIntervalRef.current);
        }
      }, 100);

      source.start();
    } catch (e) {
      console.error("Playback error", e);
      stopAudio();
    }
  };

  const handlePlayAudio = async (text: string, msgId: string) => {
    if (playingMessageId === msgId) {
      stopAudio();
      return;
    }

    setIsLoading(true); 
    try {
      const audioData = await generateSpeech(text);
      if (audioData) {
        await playAudioData(audioData, msgId);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleSendMessage = async (text: string, attachment?: string) => {
    if (!currentChatId) return;

    const userMsg: Message = {
      id: generateId(),
      text,
      sender: Sender.User,
      timestamp: Date.now(),
      attachment: attachment
    };

    setChats(prev => prev.map(c => {
      if (c.id === currentChatId) {
        const newTitle = c.messages.length === 0 
          ? (text.slice(0, 30) || "Image sent...") 
          : c.title;
        return {
          ...c,
          title: newTitle,
          messages: [...c.messages, userMsg],
          updatedAt: Date.now()
        };
      }
      return c;
    }));

    setIsLoading(true);

    try {
      const activeChat = chats.find(c => c.id === currentChatId);
      const history = activeChat ? activeChat.messages : [];

      const response = await sendMessageToGemini(
        text, 
        attachment,
        history, 
        settings.memoryEnabled, 
        settings.flirtLevel || 3,
        settings.customMemory || '',
        settings.personaMode
      );

      const botMsg: Message = {
        id: generateId(),
        text: response.text,
        sender: Sender.Bot,
        timestamp: Date.now(),
        attachment: response.attachment
      };

      setChats(prev => prev.map(c => {
        if (c.id === currentChatId) {
          return {
            ...c,
            messages: [...c.messages, botMsg], 
            updatedAt: Date.now()
          };
        }
        return c;
      }));
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const clearAllData = () => {
    setChats([]);
    setCurrentChatId(null);
    setView('home');
    setIsSettingsOpen(false);
    localStorage.removeItem('arohi_chats');
    localStorage.removeItem('arohi_settings');
    setSettings({
      memoryEnabled: true,
      theme: 'dark',
      flirtLevel: 3, 
      personaMode: 'romantic',
      customMemory: ''
    });
  };

  return (
    <div className="font-sans text-slate-200">
      {isLocked && settings.passcode && (
        <LockScreen 
          storedPin={settings.passcode} 
          onUnlock={() => setIsLocked(false)} 
        />
      )}

      {view === 'home' ? (
        <HomeHero onStartChat={handleStartChat} />
      ) : (
        <ChatInterface 
          currentChatId={currentChatId}
          chats={chats}
          settings={settings}
          onSendMessage={handleSendMessage}
          onNewChat={createNewChat}
          onSelectChat={setCurrentChatId}
          onDeleteChat={deleteChat}
          onOpenSettings={() => setIsSettingsOpen(true)}
          onPlayAudio={handlePlayAudio}
          isLoading={isLoading}
          playingMessageId={playingMessageId}
          playbackProgress={playbackProgress}
          audioVolume={audioVolume}
          onVolumeChange={setAudioVolume}
        />
      )}

      <SettingsModal 
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        onUpdateSettings={setSettings}
        onClearAllData={clearAllData}
      />
    </div>
  );
};

export default App;

