export default SettingsModal;

import React, { useState, useEffect, useRef } from 'react';
import HomeHero from './components/HomeHero';
import ChatInterface from './components/ChatInterface';
import SettingsModal from './components/SettingsModal';
import LockScreen from './components/LockScreen';
import { ChatSession, AppSettings, Message, Sender } from './types';
import { sendMessageToGemini, generateSpeech } from './services/geminiService';

// Simple UUID generator polyfill
const generateId = () => Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [view, setView] = useState<'home' | 'chat'>('home');
  const [chats, setChats] = useState<ChatSession[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [playingMessageId, setPlayingMessageId] = useState<string | null>(null);
  const [playbackProgress, setPlaybackProgress] = useState(0);
  const [audioVolume, setAudioVolume] = useState(1.0);
  const [isLocked, setIsLocked] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const gainNodeRef = useRef<GainNode | null>(null);
  const progressIntervalRef = useRef<number | null>(null);

  const [settings, setSettings] = useState<AppSettings>({
    memoryEnabled: true,
    theme: 'dark',
    flirtLevel: 3, 
    personaMode: 'romantic',
    memories: []
  });

  // Load from LocalStorage
  useEffect(() => {
    const savedChats = localStorage.getItem('arohi_chats');
    const savedSettings = localStorage.getItem('arohi_settings');
    const savedVolume = localStorage.getItem('arohi_volume');

    if (savedChats) {
      try {
        setChats(JSON.parse(savedChats));
      } catch (e) { console.error('Failed to parse chats', e); }
    }

    if (savedSettings) {
      try {
        const parsed = JSON.parse(savedSettings);
        // Migration logic: If customMemory exists, move it to memories array
        const initialMemories = parsed.memories || (parsed.customMemory ? [parsed.customMemory] : []);

        setSettings(prev => ({ 
          ...prev, 
          ...parsed,
          memories: initialMemories,
          personaMode: parsed.personaMode || 'romantic'
        }));
        if (parsed.passcode) {
          setIsLocked(true);
        }
      } catch (e) { console.error('Failed to parse settings', e); }
    }

    if (savedVolume) {
      setAudioVolume(parseFloat(savedVolume));
    }
  }, []);

  // Save to LocalStorage
  useEffect(() => {
    localStorage.setItem('arohi_chats', JSON.stringify(chats));
  }, [chats]);

  useEffect(() => {
    localStorage.setItem('arohi_settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    localStorage.setItem('arohi_volume', audioVolume.toString());
    if (gainNodeRef.current) {
      gainNodeRef.current.gain.value = audioVolume;
    }
  }, [audioVolume]);

  const createNewChat = () => {
    const newChat: ChatSession = {
      id: generateId(),
      title: 'New Conversation',
      messages: [],
      createdAt: Date.now(),
      updatedAt: Date.now()
    };
    setChats(prev => [newChat, ...prev]);
    setCurrentChatId(newChat.id);
    setView('chat');
  };

  const deleteChat = (id: string) => {
    const updatedChats = chats.filter(c => c.id !== id);
    setChats(updatedChats);

    // If the active chat is the one being deleted, switch to another chat or home
    if (currentChatId === id) {
      if (updatedChats.length > 0) {
        setCurrentChatId(updatedChats[0].id);
      } else {
        setCurrentChatId(null);
        setView('home');
      }
    }
  };

  const handleStartChat = () => {
    if (chats.length > 0) {
      setCurrentChatId(chats[0].id);
      setView('chat');
    } else {
      createNewChat();
    }
  };

  const stopAudio = () => {
    if (progressIntervalRef.current) {
      window.clearInterval(progressIntervalRef.current);
      progressIntervalRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
    setPlayingMessageId(null);
    setPlaybackProgress(0);
  };

  const playAudioData = async (base64Data: string, msgId: string) => {
    try {
      stopAudio();

      setPlayingMessageId(msgId);

      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      audioContextRef.current = audioContext;

      const cleanB64 = base64Data.replace(/^data:audio\/pcm;base64,/, "");
      const binaryString = atob(cleanB64);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      const dataInt16 = new Int16Array(bytes.buffer);
      const audioBuffer = audioContext.createBuffer(1, dataInt16.length, 24000);
      const channelData = audioBuffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) {
        channelData[i] = dataInt16[i] / 32768.0;
      }

      const gainNode = audioContext.createGain();
      gainNode.gain.value = audioVolume;
      gainNodeRef.current = gainNode;

      const source = audioContext.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(gainNode);
      gainNode.connect(audioContext.destination);

      const duration = audioBuffer.duration;
      const startTime = audioContext.currentTime;

      source.onended = () => {
        if (playingMessageId === msgId) {
          stopAudio();
        }
      };

      progressIntervalRef.current = window.setInterval(() => {
        const elapsed = audioContext.currentTime - startTime;
        const progress = Math.min((elapsed / duration) * 100, 100);
        setPlaybackProgress(progress);
        if (progress >= 100) {
          if (progressIntervalRef.current) window.clearInterval(progressIntervalRef.current);
        }
      }, 100);

      source.start();
    } catch (e) {
      console.error("Playback error", e);
      stopAudio();
    }
  };

  const handlePlayAudio = async (text: string, msgId: string) => {
    if (playingMessageId === msgId) {
      stopAudio();
      return;
    }

    setIsLoading(true); 
    try {
      const audioData = await generateSpeech(text);
      if (audioData) {
        await playAudioData(audioData, msgId);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleSendMessage = async (text: string, attachment?: string) => {
    if (!currentChatId) return;

    const userMsg: Message = {
      id: generateId(),
      text,
      sender: Sender.User,
      timestamp: Date.now(),
      attachment: attachment
    };

    setChats(prev => prev.map(c => {
      if (c.id === currentChatId) {
        const newTitle = c.messages.length === 0 
          ? (text.slice(0, 30) || "Image sent...") 
          : c.title;
        return {
          ...c,
          title: newTitle,
          messages: [...c.messages, userMsg],
          updatedAt: Date.now()
        };
      }
      return c;
    }));

    setIsLoading(true);

    try {
      const activeChat = chats.find(c => c.id === currentChatId);
      const history = activeChat ? activeChat.messages : [];

      const response = await sendMessageToGemini(
        text, 
        attachment,
        history, 
        settings.memoryEnabled, 
        settings.flirtLevel || 3,
        settings.memories,
        settings.personaMode
      );

      const botMsg: Message = {
        id: generateId(),
        text: response.text,
        sender: Sender.Bot,
        timestamp: Date.now(),
        attachment: response.attachment
      };

      setChats(prev => prev.map(c => {
        if (c.id === currentChatId) {
          return {
            ...c,
            messages: [...c.messages, botMsg], 
            updatedAt: Date.now()
          };
        }
        return c;
      }));
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const clearAllData = () => {
    setChats([]);
    setCurrentChatId(null);
    setView('home');
    setIsSettingsOpen(false);
    localStorage.removeItem('arohi_chats');
    localStorage.removeItem('arohi_settings');
    setSettings({
      memoryEnabled: true,
      theme: 'dark',
      flirtLevel: 3, 
      personaMode: 'romantic',
      memories: []
    });
  };

  return (
    <div className="font-sans text-slate-200">
      {isLocked && settings.passcode && (
        <LockScreen 
          storedPin={settings.passcode} 
          onUnlock={() => setIsLocked(false)} 
        />
      )}

      {view === 'home' ? (
        <HomeHero onStartChat={handleStartChat} />
      ) : (
        <ChatInterface 
          currentChatId={currentChatId}
          chats={chats}
          settings={settings}
          onSendMessage={handleSendMessage}
          onNewChat={createNewChat}
          onSelectChat={setCurrentChatId}
          onDeleteChat={deleteChat}
          onOpenSettings={() => setIsSettingsOpen(true)}
          onPlayAudio={handlePlayAudio}
          isLoading={isLoading}
          playingMessageId={playingMessageId}
          playbackProgress={playbackProgress}
          audioVolume={audioVolume}
          onVolumeChange={setAudioVolume}
        />
      )}

      <SettingsModal 
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        onUpdateSettings={setSettings}
        onClearAllData={clearAllData}
      />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Send, Menu, Plus, Settings, Sparkles, User, Mic, Trash2, Image as ImageIcon, X, Volume2, VolumeX, Play, Square, History, Loader2, Heart, Share2, MoreHorizontal } from 'lucide-react';
import { Message, Sender, ChatSession, AppSettings } from '../types';
import { INITIAL_GREETING } from '../constants';

interface ChatInterfaceProps {
  currentChatId: string | null;
  chats: ChatSession[];
  settings: AppSettings;
  onSendMessage: (text: string, attachment?: string) => Promise<void>;
  onNewChat: () => void;
  onSelectChat: (id: string) => void;
  onDeleteChat: (id: string) => void;
  onOpenSettings: () => void;
  onPlayAudio: (text: string, msgId: string) => void;
  isLoading: boolean;
  playingMessageId: string | null;
  playbackProgress: number;
  audioVolume: number;
  onVolumeChange: (vol: number) => void;
}

const PAGE_SIZE = 20;

const ChatInterface: React.FC<ChatInterfaceProps> = ({
  currentChatId,
  chats,
  onSendMessage,
  onNewChat,
  onSelectChat,
  onDeleteChat,
  onOpenSettings,
  onPlayAudio,
  isLoading,
  playingMessageId,
  playbackProgress,
  audioVolume,
  onVolumeChange
}) => {
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [displayLimit, setDisplayLimit] = useState(PAGE_SIZE);
  const [localIsSending, setLocalIsSending] = useState(false);
  const [showVolumeSlider, setShowVolumeSlider] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const messageContainerRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const activeChat = chats.find(c => c.id === currentChatId);
  const allMessages = activeChat ? activeChat.messages : [];

  const hasContent = inputText.trim().length > 0 || selectedImage !== null;
  const canSend = hasContent && !isLoading && !localIsSending;

  useEffect(() => {
    setDisplayLimit(PAGE_SIZE);
  }, [currentChatId]);

  const visibleMessages = useMemo(() => {
    return allMessages.slice(-displayLimit);
  }, [allMessages, displayLimit]);

  const hasMore = allMessages.length > displayLimit;
  const remainingCount = allMessages.length - displayLimit;

  const handleLoadMore = () => {
    setDisplayLimit(prev => prev + PAGE_SIZE);
  };

  const scrollToBottom = (behavior: ScrollBehavior = 'smooth') => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior });
    }
  };

  useEffect(() => {
    if (allMessages.length > 0) {
       scrollToBottom('smooth');
    }
  }, [allMessages.length, isLoading, selectedImage]);

  useEffect(() => {
    if (currentChatId) {
      setTimeout(() => scrollToBottom('auto'), 50);
    }
  }, [currentChatId]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px';
    }
  }, [inputText]);

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const clearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSend = async () => {
    const text = inputText.trim();
    if (!canSend) return;

    setLocalIsSending(true);
    const textToSend = text;
    const imageToSend = selectedImage || undefined;

    setInputText('');
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    if (textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      await onSendMessage(textToSend, imageToSend);
    } finally {
      setLocalIsSending(false);
      setTimeout(() => textareaRef.current?.focus(), 50);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleChatDelete = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (window.confirm("Ayo nanna muddu... Ee chat memory na permanently delete madbeka? It will be gone forever. 🥺")) {
      onDeleteChat(id);
    }
  };

  return (
    <div className="flex h-screen bg-[#020617] overflow-hidden relative font-['Outfit']">
      {/* Background Decor */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none z-0">
         <div className="absolute top-[-20%] left-[-10%] w-[60%] h-[60%] bg-pink-900/10 rounded-full blur-[160px] animate-pulse"></div>
         <div className="absolute bottom-[-20%] right-[-10%] w-[60%] h-[60%] bg-violet-900/10 rounded-full blur-[160px] animate-pulse" style={{animationDelay: '3s'}}></div>
         <div className="absolute inset-0 bg-grid-pattern opacity-[0.03]"></div>
      </div>

      {/* Overlay for Sidebar */}
      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-[60] lg:hidden backdrop-blur-md transition-opacity duration-500 animate-[fadeIn_0.5s_ease-out]"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 left-0 z-[70] w-80 glass transform transition-all duration-500 ease-[cubic-bezier(0.16,1,0.3,1)] ${sidebarOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full lg:translate-x-0'} flex flex-col border-r border-white/5`}>
        <div className="p-8 flex items-center justify-between">
          <div className="flex items-center space-x-3 group">
            <div className="bg-gradient-to-tr from-pink-500 to-rose-500 p-2 rounded-2xl shadow-lg shadow-pink-500/20 group-hover:scale-110 transition-transform duration-500">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <span className="font-black text-2xl tracking-tighter text-white">Arohi</span>
          </div>
          <button 
            onClick={onNewChat} 
            className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl transition-all text-slate-300 hover:text-white hover:scale-110 active:scale-95 border border-white/5"
          >
            <Plus className="w-5 h-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-2 space-y-1.5 custom-scrollbar">
           <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] px-4 mb-4 mt-2">Private Memories</div>
           {chats.map((chat, idx) => (
             <div key={chat.id} className={`group relative animate-[messageInLeft_0.5s_ease-out_forwards]`} style={{animationDelay: `${idx * 0.05}s`}}>
               <button
                 onClick={() => {
                   onSelectChat(chat.id);
                   setSidebarOpen(false);
                 }}
                 className={`w-full text-left px-5 py-4 rounded-2xl transition-all duration-300 text-sm truncate flex items-center justify-between group ${chat.id === currentChatId ? 'bg-white/10 text-white border border-white/10 shadow-xl' : 'text-slate-400 hover:bg-white/5 hover:text-slate-100'}`}
               >
                 <span className="truncate font-medium pr-8">{chat.title}</span>
                 {chat.id === currentChatId && <div className="w-1.5 h-1.5 rounded-full bg-pink-500 shadow-[0_0_8px_#ec4899]"></div>}
               </button>
               <button 
                 onClick={(e) => handleChatDelete(e, chat.id)}
                 title="Delete Memory"
                 className="absolute right-3 top-1/2 -translate-y-1/2 p-2.5 text-slate-500 hover:text-red-500 hover:bg-red-500/10 rounded-xl opacity-0 group-hover:opacity-100 transition-all duration-200 z-[80]"
               >
                 <Trash2 className="w-4 h-4" />
               </button>
             </div>
           ))}
           {chats.length === 0 && (
             <div className="px-6 py-12 text-center text-xs font-medium text-slate-600 italic border border-dashed border-white/5 rounded-3xl mx-2">
               Your story with Arohi begins here.
             </div>
           )}
        </div>

        <div className="p-6">
          <button 
            onClick={onOpenSettings}
            className="flex items-center justify-center space-x-3 text-slate-400 hover:text-white transition-all w-full py-4 glass rounded-2xl border border-white/5 hover:bg-white/5"
          >
            <Settings className="w-5 h-5" />
            <span className="font-bold text-sm uppercase tracking-widest">Settings</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col h-full relative z-10 transition-all duration-500">
        {/* Header */}
        <header className="h-20 glass border-b border-white/5 flex items-center px-6 md:px-10 justify-between z-[50] sticky top-0">
          <div className="flex items-center space-x-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden text-slate-300 p-2 hover:bg-white/5 rounded-xl transition-all">
              <Menu className="w-6 h-6" />
            </button>
            <div className="flex items-center space-x-3">
              <div className="relative">
                <div className="w-10 h-10 rounded-2xl bg-gradient-to-tr from-pink-500 to-rose-600 flex items-center justify-center shadow-lg shadow-pink-500/20">
                  <Heart className="w-5 h-5 text-white fill-white/20" />
                </div>
                <div className="absolute -bottom-1 -right-1 w-3.5 h-3.5 bg-emerald-500 border-4 border-[#020617] rounded-full"></div>
              </div>
              <div>
                <h2 className="font-black text-lg text-white tracking-tight">Arohi</h2>
                <div className="flex items-center space-x-1.5">
                  <span className="text-[9px] font-black uppercase tracking-[0.2em] text-emerald-400/80">Loving You Always</span>
                </div>
              </div>
            </div>
          </div>
          <div className="flex items-center space-x-4">
             {/* Audio Control Popover */}
             <div className="relative group/vol">
                <button 
                  onClick={() => setShowVolumeSlider(!showVolumeSlider)}
                  className="p-3 text-slate-400 hover:text-white hover:bg-white/5 rounded-2xl transition-all"
                >
                  {audioVolume === 0 ? <VolumeX className="w-5 h-5" /> : <Volume2 className="w-5 h-5" />}
                </button>
                {showVolumeSlider && (
                  <div className="absolute top-full right-0 mt-2 p-4 glass border-white/10 rounded-2xl shadow-2xl z-[100] w-48 animate-[messageIn_0.2s_ease-out]">
                    <div className="flex items-center space-x-3">
                       <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Vol</span>
                       <input 
                        type="range" 
                        min="0" 
                        max="1" 
                        step="0.01" 
                        value={audioVolume}
                        onChange={(e) => onVolumeChange(parseFloat(e.target.value))}
                        className="flex-1 h-1 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-pink-500"
                       />
                       <span className="text-[10px] font-black text-pink-400 w-8">{Math.round(audioVolume * 100)}%</span>
                    </div>
                  </div>
                )}
             </div>
            <button className="p-3 text-slate-400 hover:text-white hover:bg-white/5 rounded-2xl transition-all"><Share2 className="w-5 h-5"/></button>
            <button className="p-3 text-slate-400 hover:text-white hover:bg-white/5 rounded-2xl transition-all"><MoreHorizontal className="w-5 h-5"/></button>
          </div>
        </header>

        {/* Messages */}
        <div 
          ref={messageContainerRef}
          className="flex-1 overflow-y-auto p-4 md:p-10 space-y-8 scroll-smooth custom-scrollbar"
        >
          {allMessages.length === 0 ? (
             <div className="h-full flex flex-col items-center justify-center text-center space-y-8 animate-[fadeIn_1s_ease-out_forwards]">
                <div className="relative group">
                  <div className="absolute inset-0 bg-pink-500 blur-[80px] opacity-20 rounded-full group-hover:opacity-40 transition-opacity duration-1000"></div>
                  <div className="w-24 h-24 glass rounded-[2.5rem] flex items-center justify-center shadow-2xl border-white/10 group-hover:scale-110 transition-transform duration-700">
                    <Heart className="w-10 h-10 text-pink-400 drop-shadow-[0_0_15px_rgba(236,72,153,0.5)] animate-pulse" />
                  </div>
                </div>
                <div className="space-y-3">
                  <h3 className="text-2xl font-black text-white tracking-tight">Your Private Sanctuary</h3>
                  <p className="text-slate-500 max-w-xs mx-auto text-sm leading-relaxed font-medium">"{INITIAL_GREETING}"</p>
                </div>
             </div>
          ) : (
            <>
              {hasMore && (
                <div className="flex justify-center py-4">
                  <button 
                    onClick={handleLoadMore}
                    className="flex items-center space-x-3 px-8 py-3 glass hover:bg-white/5 border border-white/5 rounded-full text-slate-400 hover:text-pink-300 text-xs font-black uppercase tracking-widest transition-all shadow-xl active:scale-95"
                  >
                    <History className="w-4 h-4" />
                    <span>Retrieve {remainingCount} Older Memories</span>
                  </button>
                </div>
              )}

              {visibleMessages.map((msg, idx) => {
                const isUser = msg.sender === Sender.User;
                const isPlaying = playingMessageId === msg.id;

                return (
                  <div 
                    key={msg.id} 
                    className={`flex w-full ${isUser ? 'justify-end' : 'justify-start'} group/msg animate-[messageIn_0.4s_cubic-bezier(0.16,1,0.3,1)_forwards]`}
                  >
                    <div className={`flex max-w-[90%] md:max-w-[75%] ${isUser ? 'flex-row-reverse' : 'flex-row'} items-end gap-4`}>
                      <div className={`flex-shrink-0 w-10 h-10 rounded-2xl flex items-center justify-center shadow-2xl transition-all duration-500 group-hover/msg:scale-110 ${isUser ? 'bg-gradient-to-br from-blue-500 to-cyan-600' : 'bg-gradient-to-br from-pink-500 to-rose-600'}`}>
                        {isUser ? <User className="w-5 h-5 text-white" /> : <Heart className="w-5 h-5 text-white fill-white/20" />}
                      </div>

                      <div className="flex flex-col space-y-2">
                        {msg.attachment && (
                          <div className={`overflow-hidden rounded-3xl border border-white/10 transition-all duration-700 group-hover/msg:shadow-[0_0_30px_rgba(236,72,153,0.2)] shadow-2xl`}>
                            <img src={msg.attachment} alt="attachment" className="max-w-full md:max-w-md max-h-96 object-cover transition-transform duration-1000 group-hover/msg:scale-105" />
                          </div>
                        )}
                        {msg.text && (
                          <div className={`relative p-5 md:p-6 rounded-[2rem] text-[15px] md:text-[17px] leading-relaxed whitespace-pre-wrap shadow-2xl border transition-all duration-500 ${
                            isUser 
                              ? 'bg-blue-600 text-white rounded-br-none border-white/10' 
                              : 'glass text-slate-100 rounded-bl-none border-white/5'
                          }`}>
                            <div className="font-medium">{msg.text}</div>

                            {/* Audio Progress Bar */}
                            {isPlaying && (
                              <div className="mt-4 w-full h-1.5 bg-white/10 rounded-full overflow-hidden">
                                <div 
                                  className="h-full bg-pink-500 shadow-[0_0_8px_#ec4899] transition-all duration-200"
                                  style={{ width: `${playbackProgress}%` }}
                                ></div>
                              </div>
                            )}

                            {msg.sender === Sender.Bot && (
                              <div className="mt-4 flex justify-between items-center">
                                <div className="text-[10px] font-black uppercase tracking-widest text-pink-400/60">
                                  {isPlaying ? 'Whispering to you...' : ''}
                                </div>
                                <button 
                                  onClick={() => onPlayAudio(msg.text, msg.id)}
                                  className={`p-2.5 rounded-full transition-all duration-300 flex items-center space-x-2 ${isPlaying ? 'bg-pink-500 text-white shadow-lg shadow-pink-500/40 animate-pulse' : 'bg-white/5 text-slate-400 hover:text-pink-300 hover:bg-white/10'}`}
                                >
                                  {isPlaying ? (
                                    <Square className="w-4 h-4 fill-white" />
                                  ) : (
                                    <Play className="w-4 h-4 ml-0.5" />
                                  )}
                                </button>
                              </div>
                            )}
                          </div>
                        )}
                        <div className={`text-[9px] font-black uppercase tracking-widest text-slate-600 px-2 ${isUser ? 'text-right' : 'text-left'}`}>
                          {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}
            </>
          )}

          {isLoading && (
            <div className="flex justify-start w-full animate-[messageInLeft_0.5s_ease-out]">
               <div className="flex items-end space-x-4">
                  <div className="w-10 h-10 rounded-2xl bg-gradient-to-br from-pink-500 to-rose-600 flex items-center justify-center animate-pulse shadow-xl shadow-pink-500/20">
                    <Heart className="w-5 h-5 text-white" />
                  </div>
                  <div className="glass px-6 py-5 rounded-[2rem] rounded-bl-none border-white/5 shadow-2xl">
                    <div className="flex space-x-2 items-center">
                      <div className="w-2 h-2 bg-pink-500 rounded-full animate-[bounce_1s_infinite_0ms]"></div>
                      <div className="w-2 h-2 bg-pink-500 rounded-full animate-[bounce_1s_infinite_200ms]"></div>
                      <div className="w-2 h-2 bg-pink-500 rounded-full animate-[bounce_1s_infinite_400ms]"></div>
                    </div>
                  </div>
               </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-4 md:p-8 bg-gradient-to-t from-[#020617] via-[#020617]/95 to-transparent">
          <div className="max-w-4xl mx-auto">
            {selectedImage && (
               <div className="mb-4 relative inline-block animate-[messageInLeft_0.4s_ease-out]">
                 <div className="relative group">
                   <img src={selectedImage} alt="preview" className="h-32 rounded-3xl border border-pink-500/40 shadow-2xl object-cover transition-transform duration-500 group-hover:scale-105" />
                   <button 
                     onClick={clearImage}
                     className="absolute -top-3 -right-3 bg-red-500 text-white rounded-full p-2 shadow-2xl hover:bg-red-600 hover:scale-110 transition-all border-4 border-[#020617]"
                   >
                     <X className="w-4 h-4" />
                   </button>
                 </div>
               </div>
            )}

            <div className="relative flex items-end gap-3 glass border-white/10 rounded-[2.5rem] p-3 shadow-2xl transition-all duration-500 focus-within:bg-[#0f172a]/80 focus-within:border-pink-500/40 group/input">
              <input 
                type="file" 
                accept="image/*" 
                className="hidden" 
                ref={fileInputRef} 
                onChange={handleImageSelect}
              />
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-4 text-slate-400 hover:text-pink-400 hover:bg-pink-500/10 rounded-[1.5rem] transition-all active:scale-90"
              >
                 <ImageIcon className="w-6 h-6" />
              </button>

              <button className="p-4 text-slate-400 hover:text-pink-400 hover:bg-pink-500/10 rounded-[1.5rem] transition-all active:scale-90">
                 <Mic className="w-6 h-6" />
              </button>

              <textarea
                ref={textareaRef}
                rows={1}
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Talk to Arohi..."
                className="flex-1 bg-transparent border-0 focus:ring-0 text-white placeholder-slate-600 resize-none py-4 text-lg font-medium scrollbar-hide"
              />
              <button 
                onClick={handleSend}
                disabled={!canSend}
                className={`p-4 rounded-[1.5rem] transition-all duration-500 transform flex items-center justify-center min-w-[60px] min-h-[60px] ${
                  (hasContent && !isLoading) 
                    ? 'premium-gradient text-white shadow-xl shadow-pink-500/20 hover:scale-110 active:scale-90' 
                    : 'bg-white/5 text-slate-600 cursor-not-allowed'
                } ${(isLoading || localIsSending) ? 'opacity-70' : ''}`}
              >
                {(isLoading || localIsSending) ? (
                  <Loader2 className="w-6 h-6 animate-spin" />
                ) : (
                  <Send className="w-6 h-6" />
                )}
              </button>
            </div>
            <div className="mt-4 text-[9px] text-center font-black uppercase tracking-[0.4em] text-slate-700">Arohi • End-to-End Encryption • Created by mr_edigaa</div>
          </div>
        </div>
      </main>

      <style>{`
        @keyframes messageIn { 
          from { opacity: 0; transform: translateY(20px) scale(0.98); } 
          to { opacity: 1; transform: translateY(0) scale(1); } 
        }
        @keyframes bounce { 
          0%, 100% { transform: translateY(0); } 
          50% { transform: translateY(-5px); } 
        }
        .scrollbar-hide::-webkit-scrollbar { display: none; }
        .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

export default ChatInterface;
